window.DOSIK=window.DOSIK||{};DOSIK["ia_law"]={"#1":[{"t":"table","title":"보험계약 · 보험계약의 법적 성질","head":["구분","내용"],"rows":[["보험계약","당사자 일방이 약정한 보험료를 지급하고, 재산 또는 생명이나 신체에 불확정한 사고가 발생할 경우에 상대방이 일정한 보험금이나 그 밖의 급여를 지급할 것을 약정함으로써 효력이 생기는 계약 · 보험금 외에 「그 밖의 급여」(현물 등)를 지급하기로 약정할 수도 있다"],["보험계약의 법적 성질 · 낙성계약","청약과 승낙의 합의만으로 성립한다 · 증권 교부는 성립요건이 아니다"],["보험계약의 법적 성질 · 불요식계약","일정한 방식을 요하지 않는다"],["보험계약의 법적 성질 · 유상·쌍무계약","보험료와 보험금 지급 약속이 대가관계에 있다 · 「유상·편무」는 틀린 표현"],["보험계약의 법적 성질 · 사행계약","보험자의 보험금 지급 책임이 우연한 사고 발생에 달려 있다"],["보험계약의 법적 성질 · 선의계약","고지의무 등 신의성실이 특히 요구된다"],["보험계약의 법적 성질 · 부합계약","보험약관에 따라 정형적으로 체결된다"]]},{"t":"table","title":"청약과 승낙 · 당사자와 관계자(손해보험)","head":["구분","내용"],"rows":[["청약과 승낙 · 맞는 표현","청약은 보험계약자가 하고 보험자가 승낙한다"],["청약과 승낙 · 틀린 표현","「보험자의 청약에 보험계약자가 승낙」"],["당사자와 관계자(손해보험) · 보험자","보험사고가 발생한 경우 보험금 지급의무를 지는 자"],["당사자와 관계자(손해보험) · 보험계약자","자기 명의로 보험계약을 체결하고 보험료 지급의무를 지는 자"],["당사자와 관계자(손해보험) · 피보험자","피보험이익의 주체로서 보험사고가 발생한 때 보험금을 받을 자"],["당사자와 관계자(손해보험) · 보험수익자","인보험에서 보험금을 지급받을 자로 지정된 자 · 손해보험에서 보험금을 받는 자는 피보험자"]]},{"t":"table","title":"소급보험과 사고의 객관적 확정 · 사고 발생 전·후의 임의해지","head":["구분","내용"],"rows":[["소급보험과 사고의 객관적 확정 · 소급보험","보험계약은 그 계약 전의 어느 시기를 보험기간의 시기로 할 수 있다 · 보험기간의 시기를 보험계약 체결 시점과 같게 하여야 하는 것은 아니다"],["소급보험과 사고의 객관적 확정 · 무효","계약 당시 보험사고가 이미 발생하였거나 발생할 수 없는 것인 때에는 그 계약은 무효(무효이지 취소 사유가 아님)"],["소급보험과 사고의 객관적 확정 · 예외","당사자 쌍방과 피보험자가 이를 알지 못한 때에는 유효. 셋 중 한 명이라도 알았으면 무효"],["소급보험과 사고의 객관적 확정 · 사례","보험사고 이미 발생을 보험계약자(B)가 알고 체결 → 무효. 발생 불가능을 계약자(A)가 알면서 체결 → 무효. A·B·C 모두 몰랐으면 유효"],["사고 발생 전·후의 임의해지 · 사고 발생 전","보험사고 발생 전에는 보험계약자가 언제든지 계약의 전부 또는 일부를 해지할 수 있다"],["사고 발생 전·후의 임의해지 · 타인을 위한 보험(제639조)","타인의 동의를 얻지 아니하거나 보험증권을 소지하지 아니하면 해지하지 못한다"],["사고 발생 전·후의 임의해지 · 사고 발생 후","보험사고로 보험금을 지급해도 보험금액이 감액되지 아니하는 보험은 사고 발생 후에도 보험계약자가 해지할 수 있다"],["사고 발생 전·후의 임의해지 · 미경과보험료","사고 발생 전 임의해지의 경우, 다른 약정이 없으면 미경과보험료의 반환을 청구할 수 있다"]]},{"t":"tree","title":"보험료 감액과 준용","root":"보험료 감액과 준용","branches":[["감액","당사자가 특별한 위험을 예기하여 보험료의 액을 정한 경우 보험기간 중 그 위험이 소멸하면 보험계약자는 그 후의 보험료 감액을 청구할 수 있다"],["준용","상법 보험편의 규정은 그 성질에 반하지 아니하는 범위에서 상호보험, 공제, 그 밖에 이에 준하는 계약에 준용한다"],["통지","피보험자는 보험사고 발생을 안 때 지체없이 보험자에게 통지를 발송하여야 한다"]]}],"#2":[{"t":"table","title":"계약 요소와 성립 · 보험계약의 성립","head":["구분","내용"],"rows":[["계약 요소와 성립 · 보조자","보험대리상, 보험설계사, 보험중개사 등(권한은 보험대리상 쟁점 참조)"],["계약 요소와 성립 · 관계자","보험자, 보험계약자, 피보험자, 보험수익자"],["계약 요소와 성립 · 보험료","보험계약자는 보험자에 대하여 보험료를 지급할 의무가 있다"],["보험계약의 성립","청약과 함께 보험료 상당액의 전부 또는 일부를 받음 → 다른 약정이 없으면 30일 내에 보험계약자에게 낙부의 통지를 발송 → 보험자의 책임 개시: 다른 약정이 없으면 최초 보험료의 지급을 받은 때"]]},{"t":"cause","title":"약관 교부·설명의무","causes":["보험자는 보험계약을 체결할 때 보험계약자에게 보험약관을 교부하고 그 약관의 중요한 내용을 설명하여야 한다(성립 후가 아님)"],"result":"의무를 위반하면 보험계약자는 보험계약이 성립한 날부터 3개월 이내에 그 계약을 취소할 수 있다","effects":["취소권자는 보험계약자(피보험자·수익자 아님)","성립일부터 1개월 시점은 취소 가능, 4개월 시점은 취소 불가","약관의 구속력 근거: 당사자가 약관을 계약 내용에 포함시키기로 합의했기 때문(계약설)","약관 내용이 이미 법령에 정해진 것을 되풀이하는 정도에 불과한 경우, 보험자는 따로 설명하지 않아도 된다"]},{"t":"tree","title":"타인을 위한 보험","root":"타인을 위한 보험","branches":[["체결","보험계약자는 위임을 받거나 받지 아니하고, 특정 또는 불특정의 타인을 위하여 보험계약을 체결할 수 있다 · 계약 체결 시 타인이 특정되어 있을 필요는 없다"],["위임이 없는 때","손해보험에서 보험계약자가 이를 보험자에게 고지하여야 하고, 고지가 없으면 타인이 계약 체결 사실을 알지 못하였다는 사유로 보험자에게 대항하지 못한다"],["이익","그 타인은 수익의 의사표시 없이 당연히 계약의 이익을 받는다"],["손해 배상","손해보험에서 보험계약자가 타인에게 사고로 생긴 손해를 배상한 때에는, 타인의 권리를 해하지 아니하는 범위에서 보험자에게 보험금액의 지급을 청구할 수 있다"],["보험료","보험계약자가 낼 의무가 있다. 보험계약자가 파산선고를 받거나 보험료 지급을 지체한 때에는, 타인이 그 권리를 포기하지 않는 한 타인도 보험료를 지급할 의무가 있다"],["지체","특정한 타인을 위한 보험에서 보험료 지급이 지체되면 보험자는 그 타인에게도 상당한 기간을 정해 최고한 후가 아니면 해제·해지하지 못한다"]]},{"t":"def","term":"대리인에 의한 체결","text":"대리인에 의하여 보험계약을 체결한 경우 대리인이 안 사유는 본인이 안 것과 동일한 것으로 한다"}],"#3":[{"t":"table","title":"증권의 교부 · 이의약관·재교부","head":["구분","내용"],"rows":[["증권의 교부 · 교부 시기","보험자는 보험계약이 성립한 때 지체없이 보험증권을 작성하여 보험계약자에게 교부하여야 한다"],["증권의 교부 · 예외","보험계약자가 보험료 전부 또는 최초 보험료를 지급하지 아니한 때에는 교부 의무가 없다"],["증권의 교부 · 연장·변경","기존 보험계약을 연장하거나 변경한 경우, 보험자는 보험증권에 그 사실을 기재함으로써 증권 교부에 갈음할 수 있다"],["증권의 교부 · 상대방","교부 상대방은 보험계약자이다. 타인을 위한 보험이라도 타인에게 교부하는 것이 아니다"],["이의약관·재교부 · 이의약관","보험계약의 당사자는 증권 교부일부터 일정한 기간 내에 한하여 증권 내용의 정부(正否)에 관한 이의를 할 수 있음을 약정할 수 있다 · 이 기간은 1월을 내리지 못한다"],["이의약관·재교부 · 재교부","증권을 멸실 또는 현저하게 훼손한 때 보험계약자는 보험자에게 재교부를 청구할 수 있고, 증권 작성 비용은 보험계약자가 부담한다"]]},{"t":"table","title":"손해보험증권의 법정기재사항","head":["호","기재사항"],"rows":[["1호","보험의 목적"],["2호","보험사고의 성질"],["3호","보험금액"],["4호","보험료와 그 지급방법"],["5호","보험기간을 정한 때에는 그 시기와 종기"],["6호","무효와 실권의 사유"],["7호","보험계약자의 주소와 성명 또는 상호"],["7호의2","피보험자의 주소, 성명 또는 상호"],["8호","보험계약의 연월일"],["9호","보험증권의 작성지와 그 작성년월일"]]},{"t":"vs","title":"증권 기재사항 여부","cols":[{"name":"기재사항","items":["증권에 기명날인 또는 서명하는 자는 보험자이다"]},{"name":"기재사항이 아닌 것","items":["보험수익자의 주소·성명","피보험자의 주민등록번호","청약철회 사유","보험료의 계산방법","보험자의 면책에 관한 사항","보험계약자의 기명날인","보험금액의 지급방법·시기"]}]},{"t":"table","title":"화재보험증권의 추가 기재사항","head":["호","기재사항"],"rows":[["1호","건물이 목적이면 그 소재지, 구조와 용도"],["2호","동산이 목적이면 그 존치한 장소의 상태와 용도"],["3호","보험가액을 정한 때에는 그 가액"],["기재사항이 아닌 것","설계감리법인의 주소·성명, 건물 시공자의 주소·성명"]]}],"#4":[{"t":"table","title":"보험대리상의 권한(제646조의2 제1항)","head":["호","권한"],"rows":[["1호","보험계약자로부터 보험료를 수령할 수 있는 권한"],["2호","보험자가 작성한 보험증권을 보험계약자에게 교부할 수 있는 권한"],["3호","보험계약자로부터 청약, 고지, 통지, 해지, 취소 등 보험계약에 관한 의사표시를 수령할 수 있는 권한"],["4호","보험계약자에게 보험계약의 체결, 변경, 해지 등 보험계약에 관한 의사표시를 할 수 있는 권한"],["법정 권한에 없는 것","보험금 수령 권한"]]},{"t":"def","term":"권한 제한","text":"보험자는 보험대리상의 제1항 각 호 권한 중 일부를 제한할 수 있다. 다만 그러한 제한을 이유로 선의의 보험계약자에게 대항하지 못한다 · 권한을 전부 제한할 수 없다는 취지가 아니라, 일부 제한은 가능하되 선의의 계약자에게 대항 불가"},{"t":"vs","title":"보험대리상과 계속적 중개자","cols":[{"name":"보험대리상","items":["제1항 제1호부터 제4호까지의 권한"]},{"name":"보험대리상이 아닌 계속적 중개자(보험설계사 등)","items":["특정한 보험자를 위하여 계속적으로 보험계약의 체결을 중개하는 자는 제1항 제1호(보험자가 작성한 영수증을 보험계약자에게 교부하는 경우만 해당)와 제2호의 권한만 있다","보험료 수령은 보험자가 작성한 영수증을 교부할 때만 가능하고, 보험자가 작성한 증권 교부 권한은 있다"]},{"name":"계속적 중개자에게 없는 권한","items":["청약·고지·통지·해지·취소 등 의사표시를 수령할 권한","보험계약의 체결·변경·해지 등 의사표시를 보험계약자에게 할 권한"]}]},{"t":"def","term":"피보험자·보험수익자에게의 적용","text":"피보험자나 보험수익자가 보험료를 지급하거나 보험계약에 관한 의사표시를 할 의무가 있는 경우에는 제1항부터 제3항까지를 그 피보험자나 보험수익자에게도 적용한다"}],"#5":[{"t":"tree","title":"고지의무자와 시기","root":"고지의무","branches":[["고지의무자","보험계약자 또는 피보험자 · 타인을 위한 손해보험의 타인(피보험자)도 고지의무를 부담"],["고지 시점","보험계약 당시"],["고지 대상","「중요한 사항」 · 보험자가 서면으로 질문한 사항은 중요한 사항으로 추정한다(간주·의제 아님)"],["대리인","보험계약자 대리인이 안 사유는 본인이 안 것과 같다"],["고지의무자가 아닌 자","보험수익자는 고지의무자가 아니다"]]},{"t":"tree","title":"해지권(제651조)","root":"고지의무 위반 해지","branches":[["요건","계약 당시 보험계약자 또는 피보험자가 고의 또는 중대한 과실로 중요한 사항을 고지하지 아니하거나 부실의 고지를 한 때"],["행사기간","보험자가 그 사실을 안 날부터 1월 내, 계약을 체결한 날부터 3년 내에 한하여 해지할 수 있다 · 안 날부터 1월이 경과하면 해지할 수 없다"],["예","고의 불고지 시 체결일부터 1월 시점에는 해지 가능 · 중과실 불고지 시 체결일부터 5년 시점에는 해지 불가(3년 초과)"],["해지할 수 없는 경우","보험자가 계약 당시 그 사실을 알았거나 중대한 과실로 알지 못한 때 · 경과실로 불고지·부실고지한 경우"]]},{"t":"cause","title":"해지의 효과","causes":["사고 발생 후라도 고지의무 위반을 이유로 해지"],"result":"보험자는 보험금 지급 책임이 없고 이미 지급한 보험금의 반환을 청구할 수 있다","effects":["고지의무 위반 사실이 보험사고 발생에 영향을 미치지 아니하였음이 증명된 경우에는 보험금을 지급할 책임이 있다","인과관계가 없음의 증명 책임은 보험계약자 측에 있다"]},{"t":"def","term":"강행규정성","text":"보험계약자가 과실 없이 중요한 사항을 불고지한 경우에도 해지할 수 있도록 하는 약관은 보험계약자에게 불리한 변경이어서 가계보험에서 허용되지 않는다 · 보험수익자가 계약 체결 시 고지의무를 부담하도록 하는 약관도 불이익 변경이어서 허용되지 않는다"}],"#6":[{"t":"def","term":"위험 변경·증가","text":"사고발생의 위험이 현저하게 변경 또는 증가된 사실이란, 그 변경·증가된 위험이 계약 체결 당시 존재했다면 보험자가 계약을 체결하지 않았거나 적어도 그 보험료로는 인수하지 않았을 것으로 인정되는 정도를 말한다","ex":["위험 변경·증가의 통지의무는 보험기간 중에 발생한다. 계약 체결 직전에 안 사실은 고지의무의 문제이다"]},{"t":"tree","title":"통지의무(제652조)","root":"위험 변경·증가 통지의무","branches":[["통지의무자","보험계약자 또는 피보험자 · 타인을 위한 손해보험의 타인(피보험자)도 통지의무를 진다 · 보험수익자는 통지의무자가 아니다"],["통지","위험이 현저하게 변경 또는 증가된 사실을 안 때 지체없이 보험자에게 통지하여야 한다"],["해태","통지를 해태한 때 보험자는 그 사실을 안 날부터 1월 내에 한하여 계약을 해지할 수 있다"],["통지를 받은 때","보험자는 1월 내에 보험료의 증액을 청구하거나 계약을 해지할 수 있다(통지를 받은 날로부터 1월, 2월 경과하면 해지 불가)"]]},{"t":"tree","title":"고의·중과실로 인한 위험 변경·증가(제653조)","root":"제653조","branches":[["요건","보험기간 중 보험계약자, 피보험자 또는 보험수익자의 고의 또는 중대한 과실로 사고발생의 위험이 현저하게 변경 또는 증가된 때"],["효과","보험자는 그 사실을 안 날부터 1월 내에 보험료의 증액을 청구하거나 계약을 해지할 수 있다"],["주체","보험수익자가 포함된다(통지의무와 다름)"],["선택","해지와 증액은 보험자가 선택한다(증액만 가능하다거나 해지만 가능하다는 말은 틀림)"],["해지 방식","해지는 의사표시로 하는 것이지 당연히 해지된 것으로 보지 않는다"]]},{"t":"cause","title":"해지의 효과(제655조)","causes":["위험변경증가 통지를 받지 못했음을 이유로 유효하게 해지","변경·증가 사실이 사고 발생에 영향을 미침"],"result":"보험자는 보험금을 지급할 책임이 없다","effects":["이미 지급한 보험금의 반환도 청구할 수 있다","변경·증가된 사실이 사고 발생에 영향을 미치지 아니하였음이 증명되면 보험금을 지급할 책임이 있다","보험자가 위험 변경을 이유로 해지하려면 그 사실을 입증하여야 한다"]}],"#7":[{"t":"table","title":"보험료 지급과 책임 개시 · 보험료 미지급","head":["구분","내용"],"rows":[["보험료 지급과 책임 개시","보험계약자는 계약 체결 후 지체없이 보험료의 전부 또는 제1회 보험료를 지급 → 보험자의 책임은 다른 약정이 없으면 최초의 보험료를 지급받은 때로부터 개시"],["보험료 미지급 · 제1회 보험료 미지급","지급하지 아니하는 경우 다른 약정이 없는 한 계약성립 후 2월이 경과하면 그 계약은 해제된 것으로 본다(별도 해제 의사표시 불요)"],["보험료 미지급 · 계속보험료 미지급","약정한 시기에 지급되지 아니하면 보험자는 상당한 기간을 정하여 보험계약자에게 최고하고, 그 기간 내에 지급되지 아니한 때 계약을 해지할 수 있다 · 최고 없이 즉시 해지할 수 없고, 「해지된 것으로 본다」도 아님 · 사고 발생 후라도 이 해지를 하면 보험자는 보험금 지급 책임이 없다 · 특정한 타인을 위한 보험에서 보험계약자가 지체한 때 보험자는 그 타인에게도 상당한 기간을 정하여 최고한 후가 아니면 계약을 해제 또는 해지하지 못한다"]]},{"t":"tree","title":"부활(제650조의2)","root":"부활","branches":[["요건","제650조제2항에 따라 보험계약이 해지되고 해지환급금이 지급되지 아니한 경우"],["절차","일정한 기간 내에 연체보험료에 약정이자를 붙여 보험자에게 지급하고 부활을 청구한다 · 제638조의2가 준용되므로 보험자는 30일 내 낙부 통지를 발송하여야 하고 해태하면 승낙한 것으로 본다"],["부활할 수 없는 경우","제1회 보험료 미지급으로 해제된 경우, 고지의무 위반·위험변경·위험증가로 해지된 경우, 해지환급금이 지급된 경우"],["부활이 가능한 경우","계속보험료 연체로 인한 해지뿐이다(2023 기출 정답 1개)"]]},{"t":"tree","title":"보험료의 감액·반환","root":"보험료의 감액·반환","branches":[["위험 소멸","특별한 위험을 예기하여 보험료를 정한 경우 그 위험이 보험기간 중 소멸하면 보험계약자는 그 후의 보험료 감액을 청구할 수 있다"],["무효","계약의 전부 또는 일부가 무효인 경우 보험계약자와 피보험자가 선의이며 중대한 과실이 없으면 보험료의 전부 또는 일부의 반환을 청구할 수 있다. 보험계약자와 보험수익자가 선의이며 중대한 과실이 없는 때에도 같다"],["임의해지","사고 발생 전 임의해지 시 다른 약정이 없으면 미경과보험료의 반환을 청구할 수 있다"],["초과보험","보험료 감액은 장래에 대하여서만 효력이 있다"]]},{"t":"table","title":"보험료 관련 시효","head":["청구권","기간"],"rows":[["보험료청구권","2년"],["보험료 또는 적립금의 반환청구권","3년"]]}],"#8":[{"t":"table","title":"무효 사유 · 해지 사유 한눈에","head":["구분","내용"],"rows":[["무효 사유 · 사고 확정","보험사고가 이미 발생하였거나 발생할 수 없는 것인 때(당사자 쌍방과 피보험자가 이를 알지 못한 때 제외)"],["무효 사유 · 초과보험","보험계약자의 사기로 체결된 초과보험"],["무효 사유 · 중복보험","보험계약자의 사기로 체결된 중복보험"],["무효 사유 · 효과","보험계약자와 피보험자(또는 수익자)가 선의·무중과실이면 보험료 반환 청구 가능 · 사기에 의한 초과·중복보험이 무효이면 보험자는 그 사실을 안 때까지의 보험료를 청구할 수 있고 보험금 지급 의무는 없다"],["해지 사유 한눈에 · 보험계약자의 임의해지","사고 발생 전(제649조)"],["해지 사유 한눈에 · 계속보험료 미지급","최고 후 해지(제650조②)"],["해지 사유 한눈에 · 고지의무 위반","안 날부터 1월, 체결일부터 3년(제651조)"],["해지 사유 한눈에 · 위험 변경·증가 통지 해태 또는 통지 후","1월(제652조)"],["해지 사유 한눈에 · 계약자 등의 고의·중과실로 위험 증가","안 날부터 1월(제653조)"],["해지 사유 한눈에 · 보험자의 파산선고","보험계약자가 해지 가능(제654조①)"]]},{"t":"tree","title":"보험자의 파산(제654조)","root":"보험자의 파산","branches":[["해지","보험자가 파산의 선고를 받은 때에는 보험계약자는 계약을 해지할 수 있다"],["효력 상실","해지하지 아니한 보험계약은 파산선고 후 3월을 경과한 때 그 효력을 잃는다"]]},{"t":"tree","title":"임의해지(제649조)","root":"임의해지","branches":[["시기","사고 발생 전에는 보험계약자가 언제든지 계약의 전부 또는 일부를 해지할 수 있다"],["타인을 위한 보험","타인의 동의를 얻지 아니하거나 보험증권을 소지하지 아니하면 해지하지 못한다"],["사고 발생 후","보험금액이 감액되지 아니하는 보험은 보험계약자가 해지할 수 있다"],["반환","해지 시 다른 약정이 없으면 미경과보험료 반환 청구 가능"]]},{"t":"cause","title":"해지의 효과(제655조)","causes":["사고 발생 후라도 제650조·651조·652조·653조에 따라 해지"],"result":"보험자는 보험금 지급 책임이 없고 이미 지급한 보험금의 반환을 청구할 수 있다","effects":["고지의무 위반 또는 위험 변경·증가가 사고 발생에 영향을 미치지 아니하였음이 증명되면 보험금을 지급할 책임이 있다","제650조 계속보험료 미지급 해지에는 이 단서가 없다"]}],"#9":[{"t":"table","title":"보험자의 면책사유","head":["면책사유","내용"],"rows":[["계약자 등의 고의·중과실(제659조)","보험사고가 보험계약자 또는 피보험자나 보험수익자의 고의 또는 중대한 과실로 인하여 생긴 때에는 보험자는 보험금액을 지급할 책임이 없다 · 경과실만으로는 면책되지 않는다(계약자·피보험자·수익자 모두 동일)"],["전쟁 기타의 변란(제660조)","당사자 간에 다른 약정이 없으면 보험자는 보험금액을 지급할 책임이 없다"],["성질·하자·자연소모(제678조)","보험의 목적의 성질, 하자 또는 자연소모로 인한 손해는 보험자가 보상할 책임이 없다"]]},{"t":"tree","title":"그 밖의 책임 제한","root":"그 밖의 책임 제한","branches":[["통지의무 해태","손해가 증가된 때에는 그 증가된 손해만 보상 책임이 없다"],["목적의 멸실","사고 발생 후 목적이 보험자 부담 외 사고로 멸실되어도 이미 생긴 손해는 보상 책임을 면하지 못한다(면책 아님)"],["열의 작용","연소 작용이 아닌 열의 작용으로 생긴 손해는 화재보험에서 보상하지 않는다"]]}],"#10":[{"t":"def","term":"재보험","text":"보험자가 보험사고로 인하여 부담할 책임에 대하여 다른 보험자와 체결하는 보험계약","ex":["원보험계약에 영향을 미치지 아니한다","보험자가 인수한 위험을 재보험자에게 분산시키는 제도이다","상법은 재보험을 물건보험의 일종이라고 규정하지 않는다"]},{"t":"tree","title":"재보험의 특례","root":"재보험","branches":[["불이익변경금지 배제","재보험은 특약으로 상법 보험편 규정을 보험계약자의 불이익으로 변경할 수 있다(제663조 단서) · 해상보험 기타 이와 유사한 보험도 같다"],["보험자대위","재보험에도 제3자에 대한 보험자대위가 적용된다"]]}],"#11":[{"t":"table","title":"소멸시효(제662조)","head":["청구권","기간"],"rows":[["보험금청구권","3년"],["보험료 또는 적립금의 반환청구권","3년"],["보험료청구권","2년"],["합산 문제","3+3+2 = 8. (2025 기출 정답 8)"]]},{"t":"vs","title":"불이익변경금지(제663조)","cols":[{"name":"원칙","items":["이 편의 규정은 당사자 간의 특약으로 보험계약자 또는 피보험자나 보험수익자의 불이익으로 변경하지 못한다","이익으로의 변경은 가능하다(약관으로도)","가계보험·생명보험은 보험수익자의 불이익으로 변경하지 못한다"]},{"name":"예외","items":["재보험 및 해상보험 기타 이와 유사한 보험의 경우에는 불이익 변경도 가능하다","보험계약자와 보험자가 대등한 경제적 지위에서 계약조건을 정하는 기업보험에서는 불이익변경금지 원칙의 적용이 배제된다"]}]},{"t":"table","title":"약관 사례(가계보험 2024 기출)","head":["약관","판단"],"rows":[["과실 없이 중요한 사항을 불고지한 경우에도 해지권을 인정하는 약관","위반(불리)"],["보험료청구권(보험자의 권리) 소멸시효를 단축하는 약관","보험계약자에게 불리하지 않아 위반이 아닌 것으로 출제됨"],["보험수익자에게 고지의무를 부담시키는 약관","위반"],["사고 발생 전이지만 일정 기간 계약자의 해지를 금지하는 약관","위반"]]},{"t":"def","term":"준용","text":"이 편의 규정은 그 성질에 반하지 아니하는 범위에서 상호보험, 공제, 그 밖에 이에 준하는 계약에 준용한다"}],"#12":[{"t":"table","title":"손해보험계약의 보험자 책임 · 피보험이익","head":["구분","내용"],"rows":[["손해보험계약의 보험자 책임 · 보험자의 책임","보험사고로 인하여 생길 피보험자의 재산상의 손해를 보상할 책임 · 보상 대상은 피보험자의 손해이지 보험수익자의 손해가 아니다"],["손해보험계약의 보험자 책임 · 피보험자","불확정한 사고가 발생하면 보험자에게 보험금 지급을 청구할 수 있다"],["피보험이익 · 보험계약의 목적","금전으로 산정할 수 있는 이익에 한하여 보험계약의 목적으로 할 수 있다 · 「보험의 목적」(물건)이 아니라 「보험계약의 목적」(피보험이익)"],["피보험이익 · 뜻","보험사고가 발생하지 않았다면 피보험자가 누렸을 경제적 이해관계(금전으로 산정 가능한 것)"],["피보험이익 · 소유자와 담보권자","동일한 건물에 대하여 소유자와 담보권자(저당권자)는 서로 다른 피보험이익을 가지므로 각자 독립한 화재보험계약을 체결할 수 있다"],["피보험이익 · 손해","피보험이익의 전부 또는 일부가 멸실되거나 감손된 것"],["피보험이익 · 보험금 지급의무","보험기간 내 보험사고가 발생하고 그로 인해 피보험자의 피보험이익에 손해가 생기면 성립 · 보험사고 발생의 입증책임은 보험금 지급을 청구하는 보험계약자 등에게 있다"]]},{"t":"table","title":"보상 범위와 산정 · 보험가액과 소방 조치","head":["구분","내용"],"rows":[["보상 범위와 산정 · 이익·보수","사고로 상실된 피보험자가 얻을 이익이나 보수는 당사자 간에 다른 약정이 없으면 보상할 손해액에 산입하지 아니한다. 약정이 있으면 산입할 수 있다"],["보상 범위와 산정 · 보험료 잔액","보험자가 손해를 보상할 때 보험료 지급 잔액이 있으면 지급기일 미도래라도 보상할 금액에서 공제할 수 있다"],["보상 범위와 산정 · 재보험","보험자는 보험사고로 인하여 부담할 책임에 대하여 다른 보험자와 재보험계약을 체결할 수 있다"],["보상 범위와 산정 · 증권 기재","무효와 실권의 사유는 손해보험증권의 기재사항이다"],["보험가액과 소방 조치 · 보험가액","당사자 간에 보험가액을 정하지 아니한 때에는 사고발생시의 가액이 보험가액이다"],["보험가액과 소방 조치 · 소방 조치","화재보험의 보험자는 소방 또는 손해 감소에 필요한 조치로 인하여 생긴 손해를 보상할 책임이 있다"],["보험가액과 소방 조치 · 대리인","대리인에 의하여 손해보험계약을 체결한 경우 대리인이 안 사유는 본인이 안 것과 같다"],["보험가액과 소방 조치 · 양도","보험목적 양도 시 양수인은 보험계약상 권리와 의무를 승계한 것으로 추정한다"]]},{"t":"tree","title":"보상 책임 제외","root":"보상 책임","branches":[["멸실","사고 발생 후 목적이 보험자 부담 외 사고로 멸실되어도 이미 생긴 손해에 대한 보상 책임을 면하지 못한다"],["자연소모","성질·하자·자연소모로 인한 손해는 보상 책임이 없다"]]},{"t":"tree","title":"책임보험(참고)","root":"책임보험","branches":[["책임","책임보험자는 피보험자가 보험기간 중의 사고로 제3자에게 배상할 책임을 진 경우 이를 보상할 책임이 있다"],["방어비용","피보험자가 제3자의 청구를 방어하기 위하여 지출한 재판상 또는 재판외의 필요비용은 보험의 목적에 포함된 것으로 하고, 피보험자는 보험자에게 그 비용의 선급을 청구할 수 있다"],["담보·공탁","피보험자가 담보 제공 또는 공탁으로 재판 집행을 면할 수 있는 경우, 보험금액의 한도 내에서 보험자에게 그 담보 제공 또는 공탁을 청구할 수 있다"],["보험자의 지시","위 행위가 보험자의 지시에 의한 것이면 손해액에 그 금액을 가산한 금액이 보험금액을 초과해도 보험자가 부담한다"]]}],"#13":[{"t":"table","title":"보험가액과 보험금액 · 기평가보험과 미평가보험","head":["구분","내용"],"rows":[["보험가액과 보험금액 · 보험가액","피보험이익을 금전적으로 산정 또는 평가한 액수"],["보험가액과 보험금액 · 보험금액","계약상 보험자의 최고 보상 한도"],["보험가액과 보험금액 · 일치 여부","보험가액과 보험금액은 일치하지 않을 수 있다"],["보험가액과 보험금액 · 전부보험","보험금액 = 보험가액"],["보험가액과 보험금액 · 초과보험","보험금액 > 보험가액"],["보험가액과 보험금액 · 일부보험","보험금액 < 보험가액"],["기평가보험과 미평가보험 · 기평가보험","당사자 간에 보험가액을 정한 때에는 그 가액은 사고발생시의 가액으로 정한 것으로 추정한다(간주 아님) · 그 가액이 사고발생시의 가액을 현저하게 초과할 때에는 사고발생시의 가액을 보험가액으로 한다(무효가 아님)"],["기평가보험과 미평가보험 · 미평가보험","당사자 간에 보험가액을 정하지 아니한 때에는 사고발생시의 가액을 보험가액으로 한다(계약체결시 가액 아님, 무효 아님)"]]},{"t":"table","title":"초과보험(제669조) · 중복보험(제672조·제673조)","head":["구분","내용"],"rows":[["초과보험(제669조) · 감액 청구","보험금액이 보험계약의 목적의 가액을 현저하게 초과한 때 보험자 또는 보험계약자는 보험료와 보험금액의 감액을 청구할 수 있다 · 보험료의 감액은 장래에 대하여서만 효력이 있다"],["초과보험(제669조) · 가액 기준","초과 여부를 가리는 가액은 계약당시의 가액에 의한다 · 보험가액이 보험기간 중에 현저하게 감소된 때에도 감액 청구를 할 수 있다"],["초과보험(제669조) · 사기","초과보험 계약이 보험계약자의 사기로 체결된 때에는 그 계약은 무효이다. 다만 보험자는 그 사실을 안 때까지의 보험료를 청구할 수 있다"],["초과보험(제669조) · 사기가 아닌 때","보험자는 보험료와 보험금액의 감액을 청구할 수 있다. 계약을 취소·해지할 수 있다는 규정은 없다"],["중복보험(제672조·제673조) · 정의","동일한 보험계약의 목적과 동일한 사고에 관하여 수개의 보험계약이 동시에 또는 순차로 체결된 경우에 그 보험금액의 총액이 보험가액을 초과한 때"],["중복보험(제672조·제673조) · 효과","보험자는 각자의 보험금액의 한도에서 연대책임을 지며, 각 보험자의 보상책임은 각자의 보험금액의 비율에 따른다"],["중복보험(제672조·제673조) · 통지","수개의 보험계약을 체결하는 경우 보험계약자는 각 보험자에 대하여 각 보험계약의 내용을 통지하여야 한다. 통지 위반에 대한 취소권 규정은 없다"],["중복보험(제672조·제673조) · 사기","사기로 체결된 중복보험은 무효이고 보험자는 그 사실을 안 때까지의 보험료를 청구할 수 있다(제669조제4항 준용)"],["중복보험(제672조·제673조) · 권리 포기","보험자 1인에 대한 권리의 포기는 다른 보험자의 권리의무에 영향을 미치지 아니한다"],["중복보험(제672조·제673조) · 공동보험","하나의 보험계약을 수인의 보험자와 체결하는 공동보험과 구별된다"]]},{"t":"table","title":"중복보험 계산 순서 · 일부보험(제674조)","head":["구분","내용"],"rows":[["중복보험 계산 순서","손해액 → 각 보험자 분담액 = 손해액 × (그 보험금액 ÷ 보험금액 총액) → 예: A 10억·B 10억, 손해 10억이면 각 5억. A가 10억을 전액 지급하면 B에게 5억 구상 → 각 보험자의 책임 한도는 자기 보험금액. 사례 2022-19: 가액 3억 아파트에 A·B 각 3억 보험 → 전손 시 각 3억씩 받는 것은 불가, A·B는 각자 3억 한도에서 연대책임"],["일부보험(제674조) · 비례보상","보험가액의 일부를 보험에 붙인 경우 보험자는 보험금액의 보험가액에 대한 비율에 따라 보상할 책임을 진다"],["일부보험(제674조) · 약정","당사자 간에 다른 약정이 있는 때에는 보험자는 보험금액의 한도 내에서 그 손해를 보상할 책임을 진다(실손보상 약정)"],["일부보험(제674조) · 공식","보상액 = 손해액 × (보험금액 ÷ 보험가액). 단 보험금액 한도. 예: 가액 2억·금액 1억, 전손 → 1억, 손해 8천만원 → 4천만원, 손해 1억원 → 5천만원"]]},{"t":"tree","title":"일부보험 특성","root":"일부보험","branches":[["일부손해","일부보험에서 일부손해 시 비례보상하므로 손해액이 보상액보다 크다"],["강행규정 아님","일부보험도 의도적으로 가능하다. 비례보상 규정은 약정으로 배제되므로 강행규정이 아니다"],["잔존물대위","일부보험에서도 잔존물대위는 인정된다(보험금액의 보험가액에 대한 비율)"],["전부보험 체결 후","물가 상승 등으로 보험가액이 현저히 오르면 일부보험이 될 수 있다"]]}],"#14":[{"t":"table","title":"사고 발생의 통지(제657조) · 보험금 지급(제658조)","head":["구분","내용"],"rows":[["사고 발생의 통지(제657조) · 의무","보험계약자 또는 피보험자나 보험수익자는 보험사고의 발생을 안 때 지체없이 보험자에게 그 통지를 발송하여야 한다"],["사고 발생의 통지(제657조) · 당사자","통지의무자는 보험계약자, 피보험자, 보험수익자 모두이다. 통지 상대방은 보험자이다"],["사고 발생의 통지(제657조) · 해태 효과","통지의무를 해태함으로 인하여 손해가 증가된 때 보험자는 그 증가된 손해를 보상할 책임이 없다. 해지권은 규정하지 않는다"],["보험금 지급(제658조) · 약정기간이 있는 경우","그 기간 내에 지급할 보험금액을 정하여 지급한다"],["보험금 지급(제658조) · 약정기간이 없는 경우","제657조제1항의 통지를 받은 후 지체없이 지급할 보험금액을 정하고, 정하여진 날부터 10일 내에 피보험자 또는 보험수익자에게 지급한다"],["보험금 지급(제658조) · 그 밖","보험계약자의 동의 없이 보험자와 피보험자 사이에 한 보험금 지급기한 유예 합의는 유효하다 · 손해보상은 원칙적으로 금전으로 하되, 당사자의 합의로 전부 또는 일부를 현물로 보상할 수 있다"]]},{"t":"tree","title":"보험자의 책임 개시·면책(관련)","root":"책임 개시와 면책","branches":[["책임 개시","다른 약정이 없으면 최초의 보험료를 지급받은 때(청약한 때·계약 성립한 때 아님)"],["고의·중과실","보험계약자 또는 피보험자나 보험수익자의 고의 또는 중대한 과실로 사고가 생긴 때 보험자는 보험금액을 지급할 책임이 없다"],["전쟁","전쟁 기타의 변란으로 사고가 생긴 때에는 다른 약정이 없으면 보험자는 지급 책임이 없다"],["파산","보험자가 파산선고를 받고 보험계약자가 해지하지 않은 채 3월이 경과하면 계약은 효력을 잃는다"],["시효","보험금 청구권은 3년의 시효로 소멸한다"]]},{"t":"tree","title":"손해액의 산정(제676조)","root":"손해액의 산정","branches":[["기준","보험자가 보상할 손해액은 그 손해가 발생한 때와 곳의 가액에 의하여 산정한다"],["신품가액","당사자 간에 다른 약정이 있는 때에는 신품가액에 의하여 손해액을 산정할 수 있다"],["비용","손해액의 산정에 관한 비용은 보험자의 부담이다"],["이익·보수","상실된 피보험자가 얻을 이익이나 보수는 다른 약정이 없으면 손해액에 산입하지 아니한다"]]},{"t":"tree","title":"보험료 잔액의 공제(제677조)","root":"보험료 잔액의 공제","branches":[["공제","보험자가 손해를 보상할 때 보험료의 지급을 받지 아니한 잔액이 있으면, 그 지급기일이 도래하지 아니한 때라도 보상할 금액에서 이를 공제할 수 있다"],["의무 아님","공제는 「할 수 있다」(의무 아님). 잔액이 있다는 이유로 즉시 해지하거나 보상 전부를 거절할 수 있다는 규정은 없다"],["멸실","보험자가 부담할 손해가 생긴 후 그 목적이 보험자 부담 외 사고로 멸실된 때에도 이미 생긴 손해를 보상할 책임을 면하지 못한다"],["자연소모","보험의 목적의 자연소모로 인한 손해는 보험자가 보상할 책임이 없다"],["손해방지 비용","손해방지 필요·유익 비용과 보상액이 보험금액을 초과해도 보험자가 부담한다"],["일부보험","일부보험에서 약정으로 보험금액의 한도 내에서 손해 전부를 보상하게 할 수 있다"]]}],"#15":[{"t":"tree","title":"손해방지의무(제680조)","root":"손해방지의무","branches":[["주체","보험계약자와 피보험자는 손해의 방지와 경감을 위하여 노력하여야 한다. 의무 주체는 보험계약자와 피보험자 둘 다이다"],["시기","의무는 보험사고 발생 이후(사고 발생을 알았을 때)의 손해 방지·경감을 위한 것이다. 사고 이전에만 부담하는 의무가 아니다"],["결과","노력한 이상 실제로 손해가 방지·경감되었는지는 묻지 않는다"]]},{"t":"tree","title":"비용의 부담","root":"손해방지 비용","branches":[["부담","손해의 방지·경감을 위하여 필요 또는 유익하였던 비용은 보험자가 부담한다"],["한도","필요·유익 비용과 보상액이 보험금액을 초과한 경우라도 보험자가 이를 부담한다(보험금액 한도 아님)"],["요건","비용 부담 요건은 비용이 필요 또는 유익했는지이고, 손해 방지에 유효하게 영향을 주었을 것은 요건이 아니다"],["사례(2023-22)","보험금액 1억원, 보상액 8천만원, 방지·경감 비용 합계 4천만원(1천+3천) → 8천+4천 = 1억 2천만원을 보험자가 부담한다. 「1억원 한도」는 틀림. 계약자·피보험자(소유자) 모두 방지 노력 의무가 있고, 각자 지출한 필요·유익 비용은 모두 보험자 부담"]]},{"t":"cause","title":"의무 위반","causes":["피보험자가 고의 또는 중과실로 손해방지의무를 위반"],"result":"보험자는 의무 위반과 상당인과관계가 있는 손해에 대하여 배상을 청구할 수 있다","effects":["상법에는 손해방지의무 위반을 이유로 한 보험자의 해지권 규정이 없다"]}],"#16":[{"t":"tree","title":"잔존물대위(제681조)","root":"잔존물대위","branches":[["요건","보험의 목적의 「전부」가 멸실하고 보험자가 「보험금액의 전부」를 지급한 때. 일부 멸실·일부 지급만으로는 성립하지 않는다"],["효과","보험자는 그 목적에 대한 피보험자의 권리를 취득한다"],["일부보험","보험자가 취득할 권리는 보험금액의 보험가액에 대한 비율에 따라 정한다"],["권리 이전 시점","보험자가 보험금액의 전부를 지급한 때 물권변동 절차 없이 이전된다(청구받은 때·절차를 마친 때 아님)"],["처분","피보험자는 보험금액 전부를 지급받은 후에는 잔존물을 임의로 처분할 수 없다"]]},{"t":"tree","title":"제3자에 대한 청구권대위(제682조)","root":"청구권대위","branches":[["요건·효과","손해가 제3자의 행위로 발생한 경우, 보험금을 지급한 보험자는 그 지급한 금액의 한도에서 제3자에 대한 보험계약자 또는 피보험자의 권리를 취득한다(지급 전이 아님, 추정 아님)"],["일부 지급","보험자가 보상할 보험금의 일부를 지급한 경우에는 피보험자의 권리를 침해하지 아니하는 범위에서 그 권리를 행사할 수 있다"],["가족","권리가 보험계약자·피보험자와 생계를 같이 하는 가족에 대한 것인 경우, 보험자는 그 권리를 취득하지 못한다. 다만 손해가 그 가족의 고의로 인하여 발생한 경우에는 권리를 취득한다"],["사례(2023-23)","경과실로 화재를 낸 거래처 지인 → 보험자는 지급액 한도에서 취득. 생계를 달리하는 자녀(중과실) → 취득 가능. 생계를 같이 하는 배우자의 고의 방화 → 취득 가능"],["취지","제3자에 대한 보험대위의 취지는 이득금지 원칙의 실현과 부당한 면책의 방지에 있다"]]},{"t":"tree","title":"청구권대위 부가","root":"청구권대위","branches":[["면책 사고","보험약관상 보험자가 면책되는 사고임에도 보험금을 지급한 경우에는 제3자에 대한 권리를 대위취득할 수 없다"],["재보험","재보험에도 제3자에 대한 보험자대위가 적용된다"]]},{"t":"vs","title":"두 대위의 비교","cols":[{"name":"잔존물대위","items":["목적의 전부 멸실 + 보험금액 전부 지급","목적에 대한 피보험자의 권리 취득(물권 등)"]},{"name":"청구권대위","items":["제3자 행위로 손해 → 보험금 지급 시 지급액 한도에서","제3자에 대한 권리 취득(채권)"]}]}],"#17":[{"t":"tree","title":"보험목적의 양도(제679조)","root":"제679조","branches":[["승계","피보험자가 보험의 목적을 양도한 때에는 양수인은 보험계약상의 권리와 의무를 승계한 것으로 추정한다. (간주가 아니다. 권리만 승계하는 것이 아니다)"],["통지","보험의 목적의 양도인 또는 양수인은 보험자에 대하여 지체없이 그 사실을 통지하여야 한다. 공동 통지가 아니라 어느 한쪽이 하면 된다"],["미통지","통지를 하지 아니한 경우 보험자의 해지권은 상법에 없다"],["사례(2023-21)","건물을 양도한 사례: 乙(양수인)은 권리·의무를 승계한 것으로 추정, 甲 또는 乙은 보험자에 지체없이 통지"]]}],"#18":[{"t":"tree","title":"화재보험자의 책임","root":"화재보험자의 책임","branches":[["책임","화재보험계약의 보험자는 화재로 인하여 생길 손해를 보상할 책임이 있다 · 화재와 손해 사이에 상당인과관계가 필요하다"],["소방 조치","보험자는 화재의 소방 또는 손해의 감소에 필요한 조치로 인하여 생긴 손해를 보상할 책임이 있다(진화용 물로 보험목적이 훼손된 손해 포함)"],["철거비","화재 건물의 철거비와 폐기물처리비는 화재와 상당인과관계가 있는 건물수리비에 포함된다"],["도난","화재로 다른 곳에 옮겨놓은 물건의 도난으로 인한 손해는 보상 대상이 아니다"],["열의 작용","연소 작용이 아닌 열의 작용으로 발생한 손해는 보상하지 않는다"],["목적","가연성 목조교량도 화재보험의 목적이 될 수 있다"]]},{"t":"tree","title":"화재보험증권(제685조)","root":"화재보험증권","branches":[["건물","제666조 기재사항 외에 건물이 목적이면 그 소재지, 구조와 용도를 기재한다"],["동산","동산이 목적이면 그 존치한 장소의 상태와 용도를 기재한다(위치한 장소만이 아님)"],["보험가액","보험가액을 정한 때에는 그 가액을 기재한다"],["제666조의 기재사항","보험의 목적, 사고의 성질, 보험금액, 보험료와 지급방법, 보험기간의 시기·종기, 무효와 실권 사유, 보험계약자의 주소·성명, 피보험자의 주소·성명, 계약 연월일, 증권 작성지·작성년월일"],["기재사항이 아닌 것","설계감리법인·시공자의 주소와 성명, 보험계약자의 주민등록번호, 보험금액의 지급방법·시기"]]},{"t":"tree","title":"피보험이익과 일부보험","root":"화재보험 관련","branches":[["피보험이익","소유자와 저당권자는 각각 다른 피보험이익을 가지며 각자 독립한 화재보험계약을 체결할 수 있다"],["일부보험","건물의 보험가액 일부를 보험에 붙인 경우, 다른 약정이 없으면 보험금액의 보험가액에 대한 비율로 보상한다"],["보험료 잔액","보험료 잔액이 있으면 지급기일 미도래라도 보상금에서 공제할 수 있다"],["양도","건물 양도 시 양수인은 권리·의무를 승계한 것으로 추정하고, 양도인 또는 양수인은 보험자에게 지체없이 통지한다"],["재보험","보험자는 다른 보험자와 재보험계약을 체결할 수 있다"]]}],"#19":[{"t":"def","term":"집합보험","text":"경제적으로 독립한 여러 물건의 집합물을 하나의 보험의 목적으로 한 보험. 집합된 물건을 일괄하여 보험의 목적으로 한다"},{"t":"tree","title":"집합보험의 특칙","root":"집합보험","branches":[["가족·사용인의 물건(제686조)","집합된 물건을 일괄하여 보험의 목적으로 한 때에는 피보험자의 가족과 사용인의 물건도 보험의 목적에 포함된 것으로 한다 · 이 경우 그 보험은 그 가족 또는 사용인을 위하여서도 체결한 것으로 본다"],["물건의 교체(제687조)","보험의 목적에 속한 물건이 보험기간 중 수시로 교체된 경우에도 「보험사고의 발생 시」에 현존한 물건은 보험의 목적에 포함된 것으로 한다 · 보험계약 체결 시에 현존하였지만 사고 발생 시에 현존하지 않는 물건은 포함되지 않는다"]]}]};
