(window.TNQ=window.TNQ||[]).push({"terms":{"미경과보험료":{"d":"보험기간 중 아직 지나지 않은 기간에 해당하는 보험료.","r":[]},"보험대리상":{"d":"특정 보험자를 위해 계속적으로 계약 체결을 대리하거나 중개하며 법이 정한 권한을 가진 자.","r":[]},"고지의무":{"d":"계약 체결 시 보험계약자 등이 중요한 사항을 보험자에게 알리고 부실하게 알리지 않을 의무.","r":["통지의무"]},"통지의무":{"d":"보험기간 중 위험이 현저히 변경 또는 증가된 사실을 안 때 지체없이 보험자에게 알릴 의무.","r":["고지의무"]},"해지환급금":{"d":"보험계약이 해지될 때 보험자가 계약자에게 돌려주는 금액.","r":[]},"재보험":{"d":"보험자가 자신이 부담한 책임을 다른 보험자에게 넘기기 위해 체결하는 보험계약.","r":[]},"불이익변경금지":{"d":"상법 보험편 규정을 특약으로 보험계약자 등에게 불리하게 바꾸지 못하게 하는 원칙.","r":[]},"피보험이익":{"d":"보험사고가 생기지 않았다면 피보험자가 누렸을 경제적 이해관계로 금전 산정이 가능한 것.","r":["보험가액"]},"보험가액":{"d":"피보험이익을 금전으로 평가한 액수로 보험자 보상의 한계를 가늠하는 기준.","r":["피보험이익"]},"보험금액":{"d":"보험계약에서 정한 보험자의 최고 보상 한도액.","r":["보험가액"]},"초과보험":{"d":"보험금액이 보험계약 목적의 가액을 현저하게 넘는 보험.","r":["중복보험","일부보험"]},"중복보험":{"d":"같은 목적과 같은 사고에 여러 보험계약을 맺어 보험금액 총액이 보험가액을 넘는 보험.","r":["초과보험"]},"일부보험":{"d":"보험가액의 일부만 보험에 붙여 보험금액이 보험가액에 못 미치는 보험.","r":["초과보험"]},"공동보험":{"d":"하나의 보험계약을 여러 보험자가 함께 체결하는 보험.","r":["중복보험"]},"손해방지의무":{"d":"보험사고 발생 후 보험계약자와 피보험자가 손해의 방지와 경감을 위해 노력할 의무.","r":[]},"잔존물대위":{"d":"목적 전부가 멸실하고 보험금액 전부를 지급한 보험자가 그 목적에 대한 피보험자의 권리를 취득하는 것.","r":[]},"보험자대위":{"d":"보험금을 지급한 보험자가 피보험자의 권리를 법률상 넘겨받는 제도를 통틀어 이르는 말.","r":["잔존물대위"]},"책임보험":{"d":"피보험자가 제3자에게 배상할 법률상 책임을 진 경우 그 손해를 보상하는 손해보험.","r":[]},"상당인과관계":{"d":"어떤 원인에서 그 결과가 생기는 것이 일반적으로 상당하다고 인정되는 관계.","r":[]},"신품가액":{"d":"손해 산정의 기준으로 약정할 수 있는 새 물건의 가격.","r":[]}},"notes":{"「보험의 목적」(물건)이 아니라 「보험계약의 목적」(피보험이익)":"물건 자체인 보험의 목적과 달리 보험계약의 목적은 그 물건에 걸린 이익인 피보험이익이에요.","「보험자의 청약에 보험계약자가 승낙」":"청약과 승낙의 주체가 거꾸로이므로 틀린 표현이며, 청약은 계약자 쪽에서 나오는 의사표시예요.","가계보험·생명보험은 보험수익자의 불이익으로 변경하지 못한다":"가계보험과 생명보험은 수익자에게 불리한 변경이 허용되지 않는 영역입니다.","가연성 목조교량도 화재보험의 목적이 될 수 있다":"불에 타기 쉬운 목조교량도 화재보험에 들 수 있는 보험의 목적입니다.","건물 양도 시 양수인은 권리·의무를 승계한 것으로 추정하고, 양도인 또는 양수인은 보험자에게 지체없이 통지한다":"건물을 넘기면 양수인이 권리와 의무를 이어받은 것으로 추정되고 양쪽 중 누군가 보험자에게 알려야 합니다.","건물을 양도한 사례: 乙(양수인)은 권리·의무를 승계한 것으로 추정, 甲 또는 乙은 보험자에 지체없이 통지":"건물을 넘겨받은 양수인은 권리와 의무를 승계한 것으로 추정되고 양도인이나 양수인이 보험자에게 곧바로 알려야 해요.","건물의 보험가액 일부를 보험에 붙인 경우, 다른 약정이 없으면 보험금액의 보험가액에 대한 비율로 보상한다":"건물을 일부만 보험에 들었다면 약정이 없는 한 가입 비율에 따라 나누어 보상받습니다.","건물이 목적이면 그 소재지, 구조와 용도":"건물이 보험의 목적이면 화재보험증권에 위치, 구조, 용도를 추가로 적습니다.","경과실로 불고지·부실고지한 경우":"경과실로 알리지 않았거나 부실하게 알린 경우에는 해지 사유가 되지 않아요.","경과실로 화재를 낸 거래처 지인 → 보험자는 지급액 한도에서 취득. 생계를 달리하는 자녀(중과실) → 취득 가능. 생계를 같이 하는 배우자의 고의 방화 → 취득 가능":"거래처 지인이 경과실로 낸 화재도 다른 사람의 행위이므로 보험자는 지급액 한도에서 권리를 얻는 사례예요.","경과실만으로는 면책되지 않는다(계약자·피보험자·수익자 모두 동일)":"과실이 가벼운 경과실만으로는 보험자가 면책되지 않으며 이는 세 사람 모두에게 같아요.","경제적으로 독립한 여러 물건의 집합물을 하나의 보험의 목적으로 한 보험. 집합된 물건을 일괄하여 보험의 목적으로 한다":"집합보험은 독립된 여러 물건을 한 덩어리로 묶어 하나의 보험으로 드는 방식이에요.","계속보험료 연체로 인한 해지뿐이다(2023 기출 정답 1개)":"부활이 가능한 것은 계속보험료를 연체해서 해지된 경우 하나뿐이에요.","계약 당시 보험계약자 또는 피보험자가 고의 또는 중대한 과실로 중요한 사항을 고지하지 아니하거나 부실의 고지를 한 때":"해지권은 계약 당시 중요한 사항을 고의나 중대한 과실로 알리지 않았거나 거짓으로 알렸을 때 생깁니다.","계약 당시 보험사고가 이미 발생하였거나 발생할 수 없는 것인 때에는 그 계약은 무효(무효이지 취소 사유가 아님)":"사고가 이미 났거나 날 수 없는 것을 대상으로 한 계약은 취소가 아니라 처음부터 무효입니다.","계약상 보험자의 최고 보상 한도":"보험금액은 계약에서 정한, 보험자가 최대로 보상할 한도 금액입니다.","계약의 전부 또는 일부가 무효인 경우 보험계약자와 피보험자가 선의이며 중대한 과실이 없으면 보험료의 전부 또는 일부의 반환을 청구할 수 있다. 보험계약자와 보험수익자가 선의이며 중대한 과실이 없는 때에도 같다":"계약이 일부나 전부 무효라도 계약자와 피보험자가 선의이고 중과실이 없다면 보험료를 돌려받을 수 있습니다.","계약 체결 시 타인이 특정되어 있을 필요는 없다":"타인을 위한 보험은 체결할 때 그 타인이 누구인지 정해져 있지 않아도 성립합니다.","고의 불고지 시 체결일부터 1월 시점에는 해지 가능":"고의로 알리지 않은 경우 체결 후 한 달 시점은 계약일 기준 삼 년 안이라 해지권이 남아 있습니다.","고지의무 등 신의성실이 특히 요구된다":"선의계약은 위험 정보를 사실대로 알리는 신의성실이 보통 계약보다 강하게 요구되는 계약입니다.","고지의무 위반 또는 위험 변경·증가가 사고 발생에 영향을 미치지 아니하였음이 증명되면 보험금을 지급할 책임이 있다":"위반이나 위험 변경이 사고와 관계없음이 증명되면 해지를 했더라도 보험금을 줘야 하죠.","고지의무 위반 사실이 보험사고 발생에 영향을 미치지 아니하였음이 증명된 경우에는 보험금을 지급할 책임이 있다":"위반 사실이 사고와 무관하다고 증명되면 해지되었더라도 보험자는 보험금을 줘야 해요.","공제는 「할 수 있다」(의무 아님). 잔액이 있다는 이유로 즉시 해지하거나 보상 전부를 거절할 수 있다는 규정은 없다":"공제는 가능하다는 것일 뿐 의무가 아니고, 잔액을 이유로 즉시 해지하거나 보상을 거절할 수 있다는 규정은 없어요.","교부 상대방은 보험계약자이다. 타인을 위한 보험이라도 타인에게 교부하는 것이 아니다":"증권을 받는 상대는 계약자이고, 타인을 위한 보험이어도 그 타인에게 따로 주는 것은 아닙니다.","권리가 보험계약자·피보험자와 생계를 같이 하는 가족에 대한 것인 경우, 보험자는 그 권리를 취득하지 못한다. 다만 손해가 그 가족의 고의로 인하여 발생한 경우에는 권리를 취득한다":"생계를 같이하는 가족에 대한 권리는 대위로 가져갈 수 없으나 고의 손해에는 예외로 가져갈 수 있습니다.","권한을 전부 제한할 수 없다는 취지가 아니라, 일부 제한은 가능하되 선의의 계약자에게 대항 불가":"권한 전체를 못 줄인다는 말이 아니고, 일부 제한은 가능하나 선의의 계약자에게는 맞서지 못한다는 것이에요.","그 가액이 사고발생시의 가액을 현저하게 초과할 때에는 사고발생시의 가액을 보험가액으로 한다(무효가 아님)":"합의한 가액이 사고 때의 가액보다 훨씬 크면 계약이 무효가 아니라 사고 때의 가액으로 낮춰 계산해요.","그 기간 내에 지급할 보험금액을 정하여 지급한다":"보험금 지급 기간을 약정했다면 그 기간 안에 보험금액을 정해 지급해야 합니다.","그 타인은 수익의 의사표시 없이 당연히 계약의 이익을 받는다":"타인을 위한 보험의 타인은 따로 받겠다는 의사표시를 하지 않아도 계약의 이익을 당연히 받아요.","금전으로 산정할 수 있는 이익에 한하여 보험계약의 목적으로 할 수 있다":"금전으로 평가할 수 있는 이익만 보험계약의 목적, 곧 피보험이익이 될 수 있습니다.","기존 보험계약을 연장하거나 변경한 경우, 보험자는 보험증권에 그 사실을 기재함으로써 증권 교부에 갈음할 수 있다":"계약을 연장하거나 바꾼 경우에는 새 증권 대신 기존 증권에 그 사실을 적는 방식으로 교부를 대신할 수 있어요.","노력한 이상 실제로 손해가 방지·경감되었는지는 묻지 않는다":"방지 노력이 요구될 뿐 실제로 손해가 줄었는지 결과는 의무 판단에 영향이 없습니다.","다른 약정이 없으면 최초의 보험료를 지급받은 때(청약한 때·계약 성립한 때 아님)":"책임은 청약했을 때나 계약이 성립했을 때가 아니라 첫 보험료를 받은 때 시작합니다.","당사자가 특별한 위험을 예기하여 보험료의 액을 정한 경우 보험기간 중 그 위험이 소멸하면 보험계약자는 그 후의 보험료 감액을 청구할 수 있다":"특별한 위험을 감안해 보험료를 정했는데 그 위험이 사라지면 이후 보험료를 깎아 달라 할 수 있습니다.","당사자 간에 다른 약정이 없으면 보험자는 보험금액을 지급할 책임이 없다":"전쟁이나 변란으로 인한 사고는 당사자가 달리 약정하지 않았다면 보험자 면책입니다.","당사자 간에 다른 약정이 있는 때에는 보험자는 보험금액의 한도 내에서 그 손해를 보상할 책임을 진다(실손보상 약정)":"비례보상 대신 실손 보상을 약정하면 보험금액 한도에서 손해 전부를 보상받을 수 있어요.","당사자 간에 다른 약정이 있는 때에는 신품가액에 의하여 손해액을 산정할 수 있다":"신품 가격으로 손해액을 정하기로 당사자가 약정했다면 그에 따라 산정할 수 있어요.","당사자 간에 보험가액을 정하지 아니한 때에는 사고발생시의 가액을 보험가액으로 한다(계약체결시 가액 아님, 무효 아님)":"미평가보험은 가액을 정하지 않았으니 계약 때가 아니라 사고가 난 때의 가액을 기준으로 합니다.","당사자 간에 보험가액을 정하지 아니한 때에는 사고발생시의 가액이 보험가액이다":"보험가액을 따로 정하지 않았다면 사고가 난 때의 가격이 보험가액이 됩니다.","당사자 간에 보험가액을 정한 때에는 그 가액은 사고발생시의 가액으로 정한 것으로 추정한다(간주 아님)":"기평가보험에서 합의한 가액은 사고 때의 가액으로 정한 것으로 추정할 뿐 확정하지는 않습니다.","당사자 쌍방과 피보험자가 이를 알지 못한 때에는 유효. 셋 중 한 명이라도 알았으면 무효":"당사자 양쪽과 피보험자가 모두 몰랐다면 유효하고, 셋 중 하나라도 알았다면 무효가 됩니다.","당사자 일방이 약정한 보험료를 지급하고, 재산 또는 생명이나 신체에 불확정한 사고가 발생할 경우에 상대방이 일정한 보험금이나 그 밖의 급여를 지급할 것을 약정함으로써 효력이 생기는 계약":"보험계약은 보험료를 내는 쪽과, 불확정한 사고 시 보험금 등을 주기로 한 쪽이 맺는 계약입니다.","대리인에 의하여 보험계약을 체결한 경우 대리인이 안 사유는 본인이 안 것과 동일한 것으로 한다":"대리인이 계약 체결 때 알고 있던 사정은 본인이 알던 것으로 취급되어 본인에게 불리하게 작용합니다.","대리인에 의하여 손해보험계약을 체결한 경우 대리인이 안 사유는 본인이 안 것과 같다":"대리인이 손해보험을 대신 체결한 때 대리인이 알았던 사정은 본인이 안 것으로 취급됩니다.","동산이 목적이면 그 존치한 장소의 상태와 용도":"동산을 보험에 들었다면 그 물건이 놓인 장소의 상태와 용도를 증권에 적게 되어 있어요.","동산이 목적이면 그 존치한 장소의 상태와 용도를 기재한다(위치한 장소만이 아님)":"동산은 그 물건이 있는 장소가 아니라 그 장소의 상태와 용도를 적는다는 점이 특징이에요.","동일한 건물에 대하여 소유자와 담보권자(저당권자)는 서로 다른 피보험이익을 가지므로 각자 독립한 화재보험계약을 체결할 수 있다":"소유자와 저당권자는 같은 건물에 걸린 이해관계가 서로 달라 각자 화재보험을 따로 들 수 있죠.","동일한 보험계약의 목적과 동일한 사고에 관하여 수개의 보험계약이 동시에 또는 순차로 체결된 경우에 그 보험금액의 총액이 보험가액을 초과한 때":"중복보험은 같은 목적과 같은 사고에 여러 보험을 들어 보험금액 합계가 보험가액을 넘는 상태입니다.","목적에 대한 피보험자의 권리 취득(물권 등)":"잔존물대위로 가져오는 것은 목적 자체에 대한 피보험자의 물권 같은 권리입니다.","목적의 전부 멸실 + 보험금액 전부 지급":"잔존물대위의 성립 조건은 목적 전부의 멸실과 보험금액 전부의 지급 두 가지예요.","무효와 실권의 사유는 손해보험증권의 기재사항이다":"무효가 되는 경우와 권리가 없어지는 실권 사유는 손해보험증권에 적는 항목입니다.","물가 상승 등으로 보험가액이 현저히 오르면 일부보험이 될 수 있다":"처음에는 전부보험이었어도 물가가 올라 보험가액이 크게 오르면 보험금액이 모자라 일부보험이 됩니다.","변경·증가된 사실이 사고 발생에 영향을 미치지 아니하였음이 증명되면 보험금을 지급할 책임이 있다":"바뀐 위험이 사고에 영향을 주지 않았다고 증명하면 해지되어도 보험금을 지급할 책임이 남습니다.","변경·증가 사실이 사고 발생에 영향을 미침":"위험이 바뀌거나 늘어난 사실이 사고의 발생에 영향을 준 경우를 가정한 조건입니다.","보상 대상은 피보험자의 손해이지 보험수익자의 손해가 아니다":"보상받는 대상이 피보험자라서 수익자가 입은 손해는 보상 범위에 들지 않아요.","보상액 = 손해액 × (보험금액 ÷ 보험가액). 단 보험금액 한도. 예: 가액 2억·금액 1억, 전손 → 1억, 손해 8천만원 → 4천만원, 손해 1억원 → 5천만원":"손해액에 보험금액과 보험가액의 비율을 곱해 보상액을 구하며 보험금액을 넘지 못합니다.","보험가액과 보험금액은 일치하지 않을 수 있다":"보험가액은 이익의 평가액이고 보험금액은 계약상 한도라서 두 금액이 같지 않을 수 있어요.","보험가액을 정한 때에는 그 가액":"보험가액을 당사자가 미리 합의해 정했다면 그 금액을 화재보험증권에 적어야 합니다.","보험가액을 정한 때에는 그 가액을 기재한다":"보험가액을 따로 합의한 경우에 한해 증권에 그 금액이 기재됩니다.","보험가액의 일부를 보험에 붙인 경우 보험자는 보험금액의 보험가액에 대한 비율에 따라 보상할 책임을 진다":"일부보험은 보험가액 중 일부만 보험에 든 경우여서 보험자는 가입 비율만큼만 보상합니다.","보험가액이 보험기간 중에 현저하게 감소된 때에도 감액 청구를 할 수 있다":"보험기간 중에 가액이 크게 떨어진 경우에도 초과보험으로 보아 감액을 청구할 수 있죠.","보험계약은 그 계약 전의 어느 시기를 보험기간의 시기로 할 수 있다":"소급보험은 계약 이전의 시점부터 보험기간이 시작되도록 정하는 것이 허용된다는 뜻이에요.","보험계약의 당사자는 증권 교부일부터 일정한 기간 내에 한하여 증권 내용의 정부(正否)에 관한 이의를 할 수 있음을 약정할 수 있다":"이의약관은 증권 내용이 맞는지에 대해 일정 기간 이의를 제기할 수 있다고 약정하는 조항이에요.","보험계약의 체결·변경·해지 등 의사표시를 보험계약자에게 할 권한":"체결이나 변경, 해지 같은 의사표시를 계약자에게 할 권한도 계속적 중개자에게는 없죠.","보험계약자가 과실 없이 중요한 사항을 불고지한 경우에도 해지할 수 있도록 하는 약관은 보험계약자에게 불리한 변경이어서 가계보험에서 허용되지 않는다":"과실이 없어도 불고지를 이유로 해지하는 약관은 계약자에게 불리하게 법을 바꾸는 것이라 가계보험에서는 효력이 없어요.","보험계약자가 낼 의무가 있다. 보험계약자가 파산선고를 받거나 보험료 지급을 지체한 때에는, 타인이 그 권리를 포기하지 않는 한 타인도 보험료를 지급할 의무가 있다":"보험료는 원칙적으로 계약자가 내지만, 계약자가 파산하거나 지체하면 타인도 권리를 포기하지 않는 한 내야 하죠.","보험계약자가 보험료 전부 또는 최초 보험료를 지급하지 아니한 때에는 교부 의무가 없다":"계약자가 보험료 전부나 최초 보험료를 내지 않았다면 보험자는 증권을 교부하지 않아도 됩니다.","보험계약자가 해지 가능(제654조①)":"보험자의 파산은 계약자에게 해지권을 주는 사유라서 계약자가 선택해 계약을 끝낼 수 있죠.","보험계약자는 계약 체결 후 지체없이 보험료의 전부 또는 제1회 보험료를 지급 → 보험자의 책임은 다른 약정이 없으면 최초의 보험료를 지급받은 때로부터 개시":"계약자는 계약 후 곧바로 보험료 전부나 첫 회분을 내야 하고, 책임은 첫 보험료를 받은 때부터 시작됩니다.","보험계약자는 보험자에 대하여 보험료를 지급할 의무가 있다":"보험료는 계약자가 보험자에게 내야 하는 대가이며 계약자의 기본 의무입니다.","보험계약자는 위임을 받거나 받지 아니하고, 특정 또는 불특정의 타인을 위하여 보험계약을 체결할 수 있다":"계약자는 위임이 있든 없든, 대상이 특정되었든 아니든 타인을 위한 보험계약을 맺을 수 있죠.","보험계약자 대리인이 안 사유는 본인이 안 것과 같다":"보험계약자의 대리인이 알던 사정은 본인이 안 것과 같게 취급되어 고지의무에도 영향을 줍니다.","보험계약자 또는 피보험자나 보험수익자는 보험사고의 발생을 안 때 지체없이 보험자에게 그 통지를 발송하여야 한다":"사고를 안 계약자나 피보험자, 수익자는 곧바로 보험자에게 통지를 보내야 합니다.","보험계약자 또는 피보험자나 보험수익자의 고의 또는 중대한 과실로 사고가 생긴 때 보험자는 보험금액을 지급할 책임이 없다":"고의나 중대한 과실로 사고를 낸 계약자, 피보험자, 수익자에게는 보험자가 보험금을 주지 않아도 되죠.","보험계약자로부터 보험료를 수령할 수 있는 권한":"보험대리상은 계약자에게서 보험료를 대신 받을 수 있는 권한을 가집니다.","보험계약자로부터 청약, 고지, 통지, 해지, 취소 등 보험계약에 관한 의사표시를 수령할 수 있는 권한":"계약자가 하는 청약, 고지, 통지, 해지, 취소 같은 의사표시를 대신 받을 수 있는 권한입니다.","보험계약자에게 보험계약의 체결, 변경, 해지 등 보험계약에 관한 의사표시를 할 수 있는 권한":"보험대리상은 계약자를 상대로 체결, 변경, 해지 같은 의사표시를 직접 할 권한도 갖고 있죠.","보험계약자에게 불리하지 않아 위반이 아닌 것으로 출제됨":"보험료청구권은 보험자 쪽 권리이므로 시효를 짧게 해도 계약자에게 불리하지 않아 위반이 아닙니다.","보험계약자와 보험자가 대등한 경제적 지위에서 계약조건을 정하는 기업보험에서는 불이익변경금지 원칙의 적용이 배제된다":"기업보험은 양쪽이 대등한 지위에서 조건을 정하므로 불이익변경금지 원칙이 배제됩니다.","보험계약자와 피보험자(또는 수익자)가 선의·무중과실이면 보험료 반환 청구 가능":"무효여도 계약자와 피보험자나 수익자가 선의이고 중과실이 없다면 보험료 반환을 청구할 수 있습니다.","보험계약자와 피보험자는 손해의 방지와 경감을 위하여 노력하여야 한다. 의무 주체는 보험계약자와 피보험자 둘 다이다":"손해방지의무는 보험계약자와 피보험자 두 사람 모두가 지는 의무예요.","보험계약자의 동의 없이 보험자와 피보험자 사이에 한 보험금 지급기한 유예 합의는 유효하다":"계약자 동의 없이 보험자와 피보험자가 합의한 지급기한 유예도 유효합니다.","보험계약자의 사기로 체결된 중복보험":"계약자가 속여서 여러 보험을 겹쳐 든 중복보험도 무효 사유에 해당하죠.","보험계약자의 사기로 체결된 초과보험":"계약자가 속여서 실제 가치보다 훨씬 큰 금액으로 맺은 초과보험은 무효가 됩니다.","보험계약자의 주소와 성명 또는 상호":"계약자가 누구인지 알 수 있도록 증권에는 보험계약자의 주소와 이름 또는 상호가 적혀 있어야 하죠.","보험계약 체결 시에 현존하였지만 사고 발생 시에 현존하지 않는 물건은 포함되지 않는다":"계약 때는 있었어도 사고 때 없었던 물건은 보험의 목적에서 빠집니다.","보험금액 1억원, 보상액 8천만원, 방지·경감 비용 합계 4천만원(1천+3천) → 8천+4천 = 1억 2천만원을 보험자가 부담한다. 「1억원 한도」는 틀림. 계약자·피보험자(소유자) 모두 방지 노력 의무가 있고, 각자 지출한 필요·유익 비용은 모두 보험자 부담":"보상액에 방지 비용을 더한 금액은 보험금액 한도를 넘더라도 모두 보험자 몫입니다.","보험금액이 감액되지 아니하는 보험은 보험계약자가 해지할 수 있다":"지급 후에도 보험금액이 그대로인 보험은 사고 이후에도 계약자가 계약을 해지할 수 있죠.","보험금액이 보험계약의 목적의 가액을 현저하게 초과한 때 보험자 또는 보험계약자는 보험료와 보험금액의 감액을 청구할 수 있다":"보험금액이 목적의 가액보다 눈에 띄게 크면 보험자나 계약자가 보험료와 보험금액을 깎아 달라고 할 수 있어요.","보험금 외에 「그 밖의 급여」(현물 등)를 지급하기로 약정할 수도 있다":"보험자가 돈 대신 현물 같은 다른 급여로 지급하기로 약정해도 보험계약으로 인정됩니다.","보험금 청구권은 3년의 시효로 소멸한다":"보험금을 청구할 권리는 삼 년이 지나면 소멸시효로 사라지는 권리입니다.","보험기간 내 보험사고가 발생하고 그로 인해 피보험자의 피보험이익에 손해가 생기면 성립":"보험금 지급의무는 보험기간 안에 사고가 나고 그 때문에 피보험이익에 손해가 생겨야 성립합니다.","보험기간을 정한 때에는 그 시기와 종기":"보험기간을 정했다면 증권에 그 시작 시점과 끝나는 시점을 적도록 법이 정하고 있습니다.","보험기간의 시기를 보험계약 체결 시점과 같게 하여야 하는 것은 아니다":"보험기간의 시작이 반드시 계약 체결일일 필요는 없고 당사자가 앞당겨 정할 수 있습니다.","보험기간 중 보험계약자, 피보험자 또는 보험수익자의 고의 또는 중대한 과실로 사고발생의 위험이 현저하게 변경 또는 증가된 때":"보험기간 중 계약자나 피보험자, 수익자의 고의나 중과실로 위험이 현저히 커지면 이 규정이 적용되죠.","보험대리상, 보험설계사, 보험중개사 등(권한은 보험대리상 쟁점 참조)":"보험대리상, 설계사, 중개사는 보험계약을 돕는 보조자이며 권한 범위가 서로 다릅니다.","보험료 감액은 장래에 대하여서만 효력이 있다":"감액 청구가 인정되어도 이미 낸 보험료는 그대로이고 장래 보험료에만 효력이 미칩니다.","보험료 수령은 보험자가 작성한 영수증을 교부할 때만 가능하고, 보험자가 작성한 증권 교부 권한은 있다":"설계사는 보험자 영수증을 건넬 때만 보험료를 받을 수 있고 증권 교부 권한은 있어요.","보험료와 보험금 지급 약속이 대가관계에 있다":"유상·쌍무계약이라 보험계약자의 보험료 납부와 보험자의 보험금 지급 약속이 서로 맞바꾸는 관계입니다.","보험료의 감액은 장래에 대하여서만 효력이 있다":"보험료 감액은 청구 이후의 장래분에만 효력이 있고 과거 보험료에는 미치지 않습니다.","보험료 잔액이 있으면 지급기일 미도래라도 보상금에서 공제할 수 있다":"납기가 안 된 보험료 잔액이 있으면 보험자가 보상금에서 미리 제할 수 있어요.","보험목적 양도 시 양수인은 보험계약상 권리와 의무를 승계한 것으로 추정한다":"보험의 목적을 넘겨받은 양수인은 보험계약상 권리와 의무를 이어받은 것으로 추정됩니다.","보험사고가 발생하지 않았다면 피보험자가 누렸을 경제적 이해관계(금전으로 산정 가능한 것)":"피보험이익은 사고가 없었더라면 피보험자가 누렸을 경제적 이해관계로, 금액으로 따질 수 있어야 합니다.","보험사고가 발생한 경우 보험금 지급의무를 지는 자":"보험자는 보험사고가 났을 때 보험금을 지급해야 하는 채무를 지는 계약 상대방입니다.","보험사고가 보험계약자 또는 피보험자나 보험수익자의 고의 또는 중대한 과실로 인하여 생긴 때에는 보험자는 보험금액을 지급할 책임이 없다":"계약자나 피보험자, 수익자의 고의나 중과실로 사고가 났다면 보험자는 보험금을 줄 책임이 없어요.","보험사고가 이미 발생하였거나 발생할 수 없는 것인 때(당사자 쌍방과 피보험자가 이를 알지 못한 때 제외)":"사고가 이미 났거나 날 수 없는 것을 대상으로 하면 무효이나 모두 몰랐다면 예외로 유효해요.","보험사고로 보험금을 지급해도 보험금액이 감액되지 아니하는 보험은 사고 발생 후에도 보험계약자가 해지할 수 있다":"사고 후 보험금액이 감액되지 않는 보험이라면 계약자에게 해지 선택권이 계속 남아 있어요.","보험사고로 인하여 생길 피보험자의 재산상의 손해를 보상할 책임":"손해보험자는 사고로 피보험자가 입은 재산상 손해를 메워 줄 책임을 집니다.","보험사고 발생의 입증책임은 보험금 지급을 청구하는 보험계약자 등에게 있다":"사고가 있었다는 사실은 보험금을 달라는 계약자 쪽이 입증해야 합니다.","보험사고 발생 전에는 보험계약자가 언제든지 계약의 전부 또는 일부를 해지할 수 있다":"보험사고가 나기 전이면 보험계약자는 이유 없이도 계약 전체나 일부를 해지할 수 있습니다.","보험사고 이미 발생을 보험계약자(B)가 알고 체결 → 무효. 발생 불가능을 계약자(A)가 알면서 체결 → 무효. A·B·C 모두 몰랐으면 유효":"사고가 벌써 났다는 사실이나 날 수 없다는 사실을 계약자가 알고 맺으면 무효가 되고 모두 몰랐으면 유효해요.","보험수익자가 계약 체결 시 고지의무를 부담하도록 하는 약관도 불이익 변경이어서 허용되지 않는다":"수익자에게 계약 때의 고지의무를 지우는 약관도 불이익 변경이라 허용되지 않죠.","보험수익자가 포함된다(통지의무와 다름)":"고의나 중과실로 위험을 키운 주체에는 수익자도 들어가므로 통지의무자와 범위가 다릅니다.","보험수익자는 고지의무자가 아니다":"수익자는 계약 당사자가 아니므로 중요 사항을 알려야 하는 고지의무자에 포함되지 않습니다.","보험수익자는 통지의무자가 아니다":"수익자는 위험 변경을 알릴 통지의무자가 아닙니다.","보험약관상 보험자가 면책되는 사고임에도 보험금을 지급한 경우에는 제3자에 대한 권리를 대위취득할 수 없다":"약관상 면책 사고에 보험금을 지급했더라도 그 지급은 대위의 근거가 안 되어 제3자 권리를 얻지 못합니다.","보험약관에 따라 정형적으로 체결된다":"부합계약은 보험자가 미리 만든 약관대로 정형적으로 맺어지고 상대방이 내용을 고치기 어려운 계약이죠.","보험의 목적, 사고의 성질, 보험금액, 보험료와 지급방법, 보험기간의 시기·종기, 무효와 실권 사유, 보험계약자의 주소·성명, 피보험자의 주소·성명, 계약 연월일, 증권 작성지·작성년월일":"일반 손해보험증권에 적는 항목으로는 보험의 목적, 사고의 성질, 금액, 기간, 무효·실권 사유 등이 있어요.","보험의 목적에 속한 물건이 보험기간 중 수시로 교체된 경우에도 「보험사고의 발생 시」에 현존한 물건은 보험의 목적에 포함된 것으로 한다":"보험기간 중 물건이 바뀌어도 사고 당시 실제로 있던 물건이 보험의 목적에 포함됩니다.","보험의 목적의 「전부」가 멸실하고 보험자가 「보험금액의 전부」를 지급한 때. 일부 멸실·일부 지급만으로는 성립하지 않는다":"잔존물대위는 목적 전부가 없어지고 보험금액 전부가 지급되어야 성립하며 일부만으로는 안 됩니다.","보험의 목적의 성질, 하자 또는 자연소모로 인한 손해는 보험자가 보상할 책임이 없다":"보험 목적물의 성질이나 하자, 자연소모에서 생긴 손해는 보험자가 보상하지 않습니다.","보험의 목적의 양도인 또는 양수인은 보험자에 대하여 지체없이 그 사실을 통지하여야 한다. 공동 통지가 아니라 어느 한쪽이 하면 된다":"양도인과 양수인 중 한쪽만 보험자에게 지체없이 통지하면 충분하고 공동 통지일 필요는 없어요.","보험의 목적의 자연소모로 인한 손해는 보험자가 보상할 책임이 없다":"보험 목적이 저절로 닳거나 줄어서 생긴 손해는 사고로 보지 않아 보상하지 않아요.","보험자, 보험계약자, 피보험자, 보험수익자":"계약 관계자는 보험금 지급자인 보험자와 계약자, 피보험자, 수익자로 이루어져 있습니다.","보험자 1인에 대한 권리의 포기는 다른 보험자의 권리의무에 영향을 미치지 아니한다":"한 보험자에 대한 권리를 포기해도 나머지 보험자들의 권리와 의무는 그대로입니다.","보험자가 계약 당시 그 사실을 알았거나 중대한 과실로 알지 못한 때":"계약 당시 보험자가 사실을 알았거나 중대한 과실로 몰랐다면 보험자 쪽 잘못이 커서 해지할 수 없습니다.","보험자가 그 사실을 안 날부터 1월 내, 계약을 체결한 날부터 3년 내에 한하여 해지할 수 있다":"보험자의 해지권은 그 사실을 안 날부터 한 달, 계약일부터 삼 년이 지나면 사라집니다.","보험자가 보상할 보험금의 일부를 지급한 경우에는 피보험자의 권리를 침해하지 아니하는 범위에서 그 권리를 행사할 수 있다":"보험금 일부만 지급했을 때는 피보험자의 권리를 해치지 않는 범위에서만 대위권을 행사할 수 있어요.","보험자가 보상할 손해액은 그 손해가 발생한 때와 곳의 가액에 의하여 산정한다":"손해액은 사고가 일어난 때와 장소의 가격을 기준으로 계산합니다.","보험자가 보험금액의 전부를 지급한 때 물권변동 절차 없이 이전된다(청구받은 때·절차를 마친 때 아님)":"권리는 보험금액 전부를 지급하는 때 별도 물권변동 절차 없이 곧바로 보험자에게 옮겨 갑니다.","보험자가 보험사고로 인하여 부담할 책임에 대하여 다른 보험자와 체결하는 보험계약":"재보험은 보험자가 떠안은 책임을 다시 다른 보험자에게 보험으로 넘기는 계약이에요.","보험자가 부담할 손해가 생긴 후 그 목적이 보험자 부담 외 사고로 멸실된 때에도 이미 생긴 손해를 보상할 책임을 면하지 못한다":"사고 후 보험자가 책임질 수 없는 다른 사고로 목적이 없어져도 이미 발생한 손해는 보상해야 합니다.","보험자가 서면으로 질문한 사항은 중요한 사항으로 추정한다(간주·의제 아님)":"보험자가 서면으로 물은 사항은 중요하다고 일단 추정할 뿐 반증이 가능하며 의제와는 다릅니다.","보험자가 손해를 보상할 때 보험료의 지급을 받지 아니한 잔액이 있으면, 그 지급기일이 도래하지 아니한 때라도 보상할 금액에서 이를 공제할 수 있다":"보험료를 덜 받은 잔액이 있으면 납기가 오지 않았더라도 보상금에서 빼고 지급할 수 있습니다.","보험자가 손해를 보상할 때 보험료 지급 잔액이 있으면 지급기일 미도래라도 보상할 금액에서 공제할 수 있다":"보험자는 보험료 미납 잔액이 있을 때 아직 납기가 오지 않았어도 보상금에서 빼고 줄 수 있습니다.","보험자가 위험 변경을 이유로 해지하려면 그 사실을 입증하여야 한다":"위험 변경을 이유로 해지하려는 보험자는 그 사실이 있었음을 스스로 입증해야 해요.","보험자가 인수한 위험을 재보험자에게 분산시키는 제도이다":"재보험은 보험자가 맡은 위험을 재보험자에게 나눠 위험을 분산하는 장치입니다.","보험자가 작성한 보험증권을 보험계약자에게 교부할 수 있는 권한":"보험대리상은 보험자가 만든 증권을 계약자에게 전달할 권한도 있어요.","보험자가 취득할 권리는 보험금액의 보험가액에 대한 비율에 따라 정한다":"일부보험이면 보험자가 가져가는 권리의 몫은 보험금액이 보험가액에서 차지하는 비율만큼입니다.","보험자가 파산선고를 받고 보험계약자가 해지하지 않은 채 3월이 경과하면 계약은 효력을 잃는다":"보험자가 파산선고를 받고 계약자가 해지하지 않은 채 석 달이 지나면 계약이 효력을 잃습니다.","보험자가 파산의 선고를 받은 때에는 보험계약자는 계약을 해지할 수 있다":"파산 선고를 받은 보험자와의 계약은 계약자가 원하면 해지로 끝낼 수 있습니다.","보험자는 1월 내에 보험료의 증액을 청구하거나 계약을 해지할 수 있다(통지를 받은 날로부터 1월, 2월 경과하면 해지 불가)":"통지를 받은 보험자는 한 달 안에 보험료를 올려 달라고 하거나 계약을 해지할 수 있고 그 뒤에는 못 합니다.","보험자는 각자의 보험금액의 한도에서 연대책임을 지며, 각 보험자의 보상책임은 각자의 보험금액의 비율에 따른다":"중복보험의 보험자들은 각자 보험금액 한도에서 연대책임을 지고 부담 비율은 각 보험금액에 비례해요.","보험자는 그 목적에 대한 피보험자의 권리를 취득한다":"잔존물대위가 성립하면 보험자는 그 목적에 대한 피보험자의 권리를 넘겨받아요.","보험자는 그 사실을 안 날부터 1월 내에 보험료의 증액을 청구하거나 계약을 해지할 수 있다":"이 경우 보험자는 안 날부터 한 달 안에 보험료 증액 청구나 해지 중 하나를 택할 수 있습니다.","보험자는 다른 보험자와 재보험계약을 체결할 수 있다":"보험자는 부담할 위험을 나누려고 다른 보험자와 재보험을 맺을 수 있어요.","보험자는 보험계약을 체결할 때 보험계약자에게 보험약관을 교부하고 그 약관의 중요한 내용을 설명하여야 한다(성립 후가 아님)":"약관 교부와 중요 내용 설명은 계약을 맺을 때 해야 하며 성립 후에 하면 의무를 다한 것이 아닙니다.","보험자는 보험계약이 성립한 때 지체없이 보험증권을 작성하여 보험계약자에게 교부하여야 한다":"보험증권은 계약이 성립한 직후 보험자가 작성해 계약자에게 건네주어야 하는 서면이에요.","보험자는 보험금을 지급할 책임이 없다":"해지가 유효하고 위험 변경이 사고에 영향을 줬다면 보험자는 보험금을 줄 책임이 없죠.","보험자는 보험금 지급 책임이 없고 이미 지급한 보험금의 반환을 청구할 수 있다":"해지가 유효하면 보험자는 보험금 지급 의무가 없고 이미 낸 보험금은 돌려 달라고 할 수 있습니다.","보험자는 보험대리상의 제1항 각 호 권한 중 일부를 제한할 수 있다. 다만 그러한 제한을 이유로 선의의 보험계약자에게 대항하지 못한다":"보험자는 대리상의 권한 일부를 줄일 수 있지만, 그 제한을 몰랐던 계약자에게는 주장하지 못합니다.","보험자는 보험료와 보험금액의 감액을 청구할 수 있다. 계약을 취소·해지할 수 있다는 규정은 없다":"사기가 아닌 초과보험이면 감액 청구가 가능하지만 취소나 해지를 정한 규정은 없어요.","보험자는 보험사고로 인하여 부담할 책임에 대하여 다른 보험자와 재보험계약을 체결할 수 있다":"보험자는 자신이 질 책임을 덜기 위해 다른 보험자와 재보험을 맺을 수 있죠.","보험자는 의무 위반과 상당인과관계가 있는 손해에 대하여 배상을 청구할 수 있다":"의무 위반과 상당한 인과관계가 있는 손해에 대해서는 보험자가 배상을 청구할 수 있어요.","보험자는 화재의 소방 또는 손해의 감소에 필요한 조치로 인하여 생긴 손해를 보상할 책임이 있다(진화용 물로 보험목적이 훼손된 손해 포함)":"소방 활동이나 손해 감소 조치로 생긴 손해, 예를 들어 진화용 물에 목적물이 젖은 손해도 보상합니다.","보험자의 보험금 지급 책임이 우연한 사고 발생에 달려 있다":"사행계약은 보험금을 줄지 여부가 우연한 사고의 발생 여부에 달려 있는 계약이에요.","보험증권의 작성지와 그 작성년월일":"증권을 어디서 언제 만들었는지 밝히기 위해 작성지와 작성 날짜를 적어야 해요.","불확정한 사고가 발생하면 보험자에게 보험금 지급을 청구할 수 있다":"피보험자는 불확정한 사고가 생기면 보험자에게 직접 보험금을 청구할 수 있는 지위에 있어요.","비용 부담 요건은 비용이 필요 또는 유익했는지이고, 손해 방지에 유효하게 영향을 주었을 것은 요건이 아니다":"비용을 보상받으려면 그 지출이 필요하거나 유익했으면 되고 실제 손해 방지에 효과가 있었을 필요는 없어요.","사고로 상실된 피보험자가 얻을 이익이나 보수는 당사자 간에 다른 약정이 없으면 보상할 손해액에 산입하지 아니한다. 약정이 있으면 산입할 수 있다":"잃어버린 기대이익이나 보수는 달리 약정하지 않으면 손해액에 넣지 않고 약정이 있으면 넣을 수 있어요.","사고발생의 위험이 현저하게 변경 또는 증가된 사실이란, 그 변경·증가된 위험이 계약 체결 당시 존재했다면 보험자가 계약을 체결하지 않았거나 적어도 그 보험료로는 인수하지 않았을 것으로 인정되는 정도를 말한다":"위험이 현저히 바뀌었다는 것은 처음부터 그 위험이었다면 보험자가 계약하지 않았거나 같은 보험료로는 받지 않았을 정도입니다.","사고 발생 전에는 보험계약자가 언제든지 계약의 전부 또는 일부를 해지할 수 있다":"사고 전에는 계약자에게 해지 자유가 있어서 계약 전체뿐 아니라 일부만 끊는 것도 가능합니다.","사고 발생 전 임의해지 시 다른 약정이 없으면 미경과보험료의 반환을 청구할 수 있다":"사고 전에 임의로 해지했다면 따로 약정이 없는 한 아직 지나지 않은 기간의 보험료를 돌려받아요.","사고 발생 전 임의해지의 경우, 다른 약정이 없으면 미경과보험료의 반환을 청구할 수 있다":"임의해지를 하면 보험기간이 남은 만큼의 보험료, 곧 미경과보험료를 돌려받을 수 있어요.","사고 발생 후라도 고지의무 위반을 이유로 해지":"고지의무 위반을 이유로 하는 해지는 이미 사고가 난 뒤에도 할 수 있습니다.","사고 발생 후라도 이 해지를 하면 보험자는 보험금 지급 책임이 없다":"최고 후 해지를 하면 사고가 난 뒤에도 보험자는 보험금을 줄 책임이 없어요.","사고 발생 후라도 제650조·651조·652조·653조에 따라 해지":"사고가 이미 났더라도 계속보험료 미납, 고지 위반, 위험 변경에 따른 해지는 효력이 있습니다.","사고 발생 후 목적이 보험자 부담 외 사고로 멸실되어도 이미 생긴 손해는 보상 책임을 면하지 못한다(면책 아님)":"사고가 난 뒤에 별개 사고로 목적이 없어져도 이미 발생한 손해에 대한 보상 책임은 남아요.","사고 발생 후 목적이 보험자 부담 외 사고로 멸실되어도 이미 생긴 손해에 대한 보상 책임을 면하지 못한다":"사고 뒤 보험자가 책임질 수 없는 사고로 목적이 없어져도 이미 생긴 손해는 보상해야 합니다.","사기로 체결된 중복보험은 무효이고 보험자는 그 사실을 안 때까지의 보험료를 청구할 수 있다(제669조제4항 준용)":"사기로 맺은 중복보험은 무효이며 보험자는 안 때까지의 보험료를 청구할 수 있습니다.","사기에 의한 초과·중복보험이 무효이면 보험자는 그 사실을 안 때까지의 보험료를 청구할 수 있고 보험금 지급 의무는 없다":"사기로 무효가 된 초과나 중복보험에서는 보험자가 안 때까지의 보험료를 받을 수 있으나 보험금은 내지 않아요.","상법 보험편의 규정은 그 성질에 반하지 아니하는 범위에서 상호보험, 공제, 그 밖에 이에 준하는 계약에 준용한다":"상법 보험편은 성질에 맞는 범위에서 상호보험이나 공제처럼 비슷한 계약에도 가져다 적용됩니다.","상법에는 손해방지의무 위반을 이유로 한 보험자의 해지권 규정이 없다":"손해방지의무를 어겼다고 보험자가 계약을 해지할 수 있다는 상법 규정은 없어요.","상법은 재보험을 물건보험의 일종이라고 규정하지 않는다":"상법에는 재보험이 물건보험에 속한다고 정한 규정이 없습니다.","상실된 피보험자가 얻을 이익이나 보수는 다른 약정이 없으면 손해액에 산입하지 아니한다":"계약자가 얻었을 이익이나 보수는 약정이 없는 한 손해액에 넣지 않습니다.","설계감리법인·시공자의 주소와 성명, 보험계약자의 주민등록번호, 보험금액의 지급방법·시기":"설계감리법인과 시공자의 인적 사항은 법정 기재사항이 아닙니다.","설계감리법인의 주소·성명, 건물 시공자의 주소·성명":"설계감리법인이나 시공자의 인적 사항은 화재보험증권의 기재사항에 들지 않습니다.","성립일부터 1개월 시점은 취소 가능, 4개월 시점은 취소 불가":"취소 기간은 계약 성립일부터 따지므로 한 달째는 취소가 가능하고 넉 달째는 기간이 지나 불가능하죠.","성질·하자·자연소모로 인한 손해는 보상 책임이 없다":"성질이나 하자, 자연소모에서 비롯된 손해는 사고가 아니므로 보상하지 않아요.","소유자와 저당권자는 각각 다른 피보험이익을 가지며 각자 독립한 화재보험계약을 체결할 수 있다":"같은 건물이라도 소유자의 이익과 저당권자의 이익은 별개여서 계약이 따로따로 성립해요.","손해가 제3자의 행위로 발생한 경우, 보험금을 지급한 보험자는 그 지급한 금액의 한도에서 제3자에 대한 보험계약자 또는 피보험자의 권리를 취득한다(지급 전이 아님, 추정 아님)":"제3자의 행위로 난 손해에서 보험금을 지급한 보험자는 지급액 한도에서 제3자에 대한 권리를 넘겨받습니다.","손해가 증가된 때에는 그 증가된 손해만 보상 책임이 없다":"통지를 게을리해서 손해가 늘어났다면 늘어난 부분에 한하여 보험자가 보상하지 않아요.","손해방지 필요·유익 비용과 보상액이 보험금액을 초과해도 보험자가 부담한다":"손해를 막으려고 쓴 필요한 비용은 보상액과 합쳐 보험금액을 넘어도 보험자가 냅니다.","손해보상은 원칙적으로 금전으로 하되, 당사자의 합의로 전부 또는 일부를 현물로 보상할 수 있다":"손해는 금전으로 보상하는 것이 원칙이지만 당사자가 합의하면 일부나 전부를 현물로 보상할 수 있어요.","손해보험에서 보험계약자가 이를 보험자에게 고지하여야 하고, 고지가 없으면 타인이 계약 체결 사실을 알지 못하였다는 사유로 보험자에게 대항하지 못한다":"위임 없이 손해보험을 들 때 계약자가 이를 알리지 않으면 타인이 몰랐다는 점을 보험자에게 주장할 수 없습니다.","손해보험에서 보험계약자가 타인에게 사고로 생긴 손해를 배상한 때에는, 타인의 권리를 해하지 아니하는 범위에서 보험자에게 보험금액의 지급을 청구할 수 있다":"계약자가 타인에게 사고 손해를 먼저 배상했다면 타인의 권리를 해치지 않는 한도에서 보험금을 청구할 수 있습니다.","손해보험에서 보험금을 받는 자는 피보험자":"손해보험은 손해를 입은 사람이 보상받는 구조라서 따로 지정된 수익자 없이 피보험자가 받습니다.","손해액 → 각 보험자 분담액 = 손해액 × (그 보험금액 ÷ 보험금액 총액) → 예: A 10억·B 10억, 손해 10억이면 각 5억. A가 10억을 전액 지급하면 B에게 5억 구상 → 각 보험자의 책임 한도는 자기 보험금액. 사례 2022-19: 가액 3억 아파트에 A·B 각 3억 보험 → 전손 시 각 3억씩 받는 것은 불가, A·B는 각자 3억 한도에서 연대책임":"중복보험은 손해액을 각 보험금액의 비율로 나누어 분담하며 각자 책임은 자기 보험금액이 한도예요.","손해액의 산정에 관한 비용은 보험자의 부담이다":"손해액을 산정하는 데 드는 비용은 계약자가 아니라 보험자가 부담합니다.","손해의 방지·경감을 위하여 필요 또는 유익하였던 비용은 보험자가 부담한다":"손해를 막거나 줄이는 데 필요하거나 유익했던 비용은 보험자가 대신 물어 주는 것이에요.","수개의 보험계약을 체결하는 경우 보험계약자는 각 보험자에 대하여 각 보험계약의 내용을 통지하여야 한다. 통지 위반에 대한 취소권 규정은 없다":"여러 보험을 든 계약자는 각 보험자에게 다른 계약 내용을 알릴 통지의무가 있으나 위반 시 취소권은 규정되지 않았습니다.","안 날부터 1월(제653조)":"위험 증가를 이유로 한 해지도 보험자가 안 날부터 한 달 안에 해야 해요.","안 날부터 1월, 체결일부터 3년(제651조)":"고지의무를 어기면 보험자는 안 날부터 한 달, 계약일부터 삼 년 안에만 해지할 수 있습니다.","안 날부터 1월이 경과하면 해지할 수 없다":"해지권 행사 기간은 안 날을 기준으로 한 달이므로 그 뒤에는 해지할 수 없어요.","약관 내용이 이미 법령에 정해진 것을 되풀이하는 정도에 불과한 경우, 보험자는 따로 설명하지 않아도 된다":"약관이 법령 내용을 그대로 반복하는 수준이면 새로운 정보가 아니어서 따로 설명할 필요가 없어요.","약관의 구속력 근거: 당사자가 약관을 계약 내용에 포함시키기로 합의했기 때문(계약설)":"계약설에 따르면 약관은 당사자가 계약 내용으로 삼기로 합의했기 때문에 구속력을 가집니다.","약정한 시기에 지급되지 아니하면 보험자는 상당한 기간을 정하여 보험계약자에게 최고하고, 그 기간 내에 지급되지 아니한 때 계약을 해지할 수 있다":"계속보험료가 밀리면 보험자가 상당한 기간을 정해 독촉한 뒤, 그 기간에도 안 내면 해지할 수 있습니다.","연소 작용이 아닌 열의 작용으로 발생한 손해는 보상하지 않는다":"불에 타는 연소 없이 열이 작용해서만 생긴 손해는 화재보험으로 보상하지 않아요.","연소 작용이 아닌 열의 작용으로 생긴 손해는 화재보험에서 보상하지 않는다":"불에 타는 연소가 아니라 열이 가해져 생긴 손해는 화재보험의 보상 대상이 아닙니다.","원보험계약에 영향을 미치지 아니한다":"재보험은 별개의 계약이어서 원래 보험계약의 효력이나 내용을 바꾸지 않아요.","위 행위가 보험자의 지시에 의한 것이면 손해액에 그 금액을 가산한 금액이 보험금액을 초과해도 보험자가 부담한다":"보험자가 지시한 행위로 든 비용이면 손해액에 더해 보험금액을 넘더라도 보험자가 모두 부담합니다.","위험 변경·증가의 통지의무는 보험기간 중에 발생한다. 계약 체결 직전에 안 사실은 고지의무의 문제이다":"통지의무는 보험기간 중 생긴 위험 증가에 관한 것이고, 계약 직전에 안 사실은 고지의무 문제입니다.","위험변경증가 통지를 받지 못했음을 이유로 유효하게 해지":"위험 변경 통지를 받지 못한 보험자는 그것을 이유로 계약을 유효하게 해지할 수 있어요.","위험이 현저하게 변경 또는 증가된 사실을 안 때 지체없이 보험자에게 통지하여야 한다":"위험이 크게 바뀌거나 늘어난 사실을 안 계약자는 곧바로 보험자에게 알려야 해요.","의무는 보험사고 발생 이후(사고 발생을 알았을 때)의 손해 방지·경감을 위한 것이다. 사고 이전에만 부담하는 의무가 아니다":"사고를 안 뒤에 손해가 번지지 않게 막고 줄여야 하는 의무이며 사고 전에만 지는 것이 아닙니다.","의무를 위반하면 보험계약자는 보험계약이 성립한 날부터 3개월 이내에 그 계약을 취소할 수 있다":"설명의무를 어긴 보험자에 대해 계약자는 성립일부터 정해진 기간 안에 계약을 취소할 수 있습니다.","이 경우 그 보험은 그 가족 또는 사용인을 위하여서도 체결한 것으로 본다":"일괄한 집합보험은 가족과 사용인을 위해서도 체결된 것으로 간주되어 그들도 보호받아요.","이 기간은 1월을 내리지 못한다":"이의 제기 기간을 약정할 때는 1개월보다 짧게 정할 수 없다는 하한이 있습니다.","이미 지급한 보험금의 반환도 청구할 수 있다":"이 경우 보험자는 이미 준 보험금까지 되돌려 달라고 청구할 수 있어요.","이익으로의 변경은 가능하다(약관으로도)":"계약자에게 유리하게 고치는 것은 약관으로도 허용되므로 금지되는 것은 불리한 변경뿐이에요.","이 편의 규정은 그 성질에 반하지 아니하는 범위에서 상호보험, 공제, 그 밖에 이에 준하는 계약에 준용한다":"상호보험이나 공제처럼 성질에 맞는 계약에도 보험편 규정을 같은 방식으로 가져다 씁니다.","이 편의 규정은 당사자 간의 특약으로 보험계약자 또는 피보험자나 보험수익자의 불이익으로 변경하지 못한다":"보험편 규정은 계약자 등에게 불리하게 특약으로 바꿀 수 없다는 불이익변경금지 원칙입니다.","인과관계가 없음의 증명 책임은 보험계약자 측에 있다":"사고와 위반 사이에 인과관계가 없다는 사실은 계약자 쪽이 증명해야 하죠.","인보험에서 보험금을 지급받을 자로 지정된 자":"보험수익자는 생명이나 신체를 대상으로 하는 인보험에서 보험금을 받는 사람으로 지정된 자입니다.","일부보험도 의도적으로 가능하다. 비례보상 규정은 약정으로 배제되므로 강행규정이 아니다":"일부보험은 일부러 가입할 수 있고 비례보상 규정은 약정으로 배제되어 강행규정이 아닙니다.","일부보험에서도 잔존물대위는 인정된다(보험금액의 보험가액에 대한 비율)":"일부보험에서도 잔존물대위가 인정되며 취득 범위는 보험금액 대 보험가액 비율로 정해집니다.","일부보험에서 약정으로 보험금액의 한도 내에서 손해 전부를 보상하게 할 수 있다":"일부보험이라도 약정이 있으면 보험금액 범위 안에서 손해 전부를 보상할 수 있습니다.","일부보험에서 일부손해 시 비례보상하므로 손해액이 보상액보다 크다":"일부보험은 비례해서 보상하므로 일부 손해에서는 받는 돈이 손해액보다 적습니다.","일정한 기간 내에 연체보험료에 약정이자를 붙여 보험자에게 지급하고 부활을 청구한다":"부활하려면 정해진 기간 안에 밀린 보험료와 약정이자를 함께 내고 청구해야 해요.","일정한 방식을 요하지 않는다":"불요식계약은 서면 같은 특정 형식을 갖추지 않아도 성립할 수 있는 계약이죠.","자기 명의로 보험계약을 체결하고 보험료 지급의무를 지는 자":"보험계약자는 자기 이름으로 계약을 맺고 보험료를 내는 사람이며 피보험자와 다를 수 있어요.","재보험 및 해상보험 기타 이와 유사한 보험의 경우에는 불이익 변경도 가능하다":"재보험과 해상보험 등에서는 불이익변경금지가 적용되지 않아 불리하게 바꿔도 됩니다.","재보험에도 제3자에 대한 보험자대위가 적용된다":"재보험자도 사고에 책임 있는 제3자에게 보험자대위를 할 수 있어요.","재보험은 특약으로 상법 보험편 규정을 보험계약자의 불이익으로 변경할 수 있다(제663조 단서)":"재보험은 특약으로 보험편 규정을 계약자에게 불리하게 바꿔도 되는 예외에 속해요.","전쟁 기타의 변란으로 사고가 생긴 때에는 다른 약정이 없으면 보험자는 지급 책임이 없다":"전쟁 같은 변란으로 생긴 사고는 달리 약정하지 않았다면 보험자에게 지급 책임이 없어요.","제1항 제1호부터 제4호까지의 권한":"보험대리상은 제1항에 적힌 네 가지 권한을 모두 가지는 사람이에요.","제1회 보험료 미지급으로 해제된 경우, 고지의무 위반·위험변경·위험증가로 해지된 경우, 해지환급금이 지급된 경우":"첫 보험료 미납으로 해제된 경우나 고지 위반 등으로 해지된 경우, 환급금이 나간 경우에는 부활이 안 됩니다.","제3자에 대한 권리 취득(채권)":"청구권대위로 가져오는 것은 제3자에 대한 채권이에요.","제3자에 대한 보험대위의 취지는 이득금지 원칙의 실현과 부당한 면책의 방지에 있다":"보험대위는 보험으로 이득을 보지 못하게 하고 제3자가 부당하게 책임을 벗는 것을 막으려는 제도예요.","제3자 행위로 손해 → 보험금 지급 시 지급액 한도에서":"청구권대위는 제삼자 때문에 생긴 손해에 보험금을 지급했을 때, 지급액 한도에서 일어납니다.","제638조의2가 준용되므로 보험자는 30일 내 낙부 통지를 발송하여야 하고 해태하면 승낙한 것으로 본다":"부활 청구를 받은 보험자가 낙부 통지를 늦게 보내면 승낙한 것으로 보는 규정이 준용됩니다.","제650조 계속보험료 미지급 해지에는 이 단서가 없다":"계속보험료 미납에 따른 해지에는 인과관계 증명으로 보험금을 받는 단서가 달려 있지 않습니다.","제650조제2항에 따라 보험계약이 해지되고 해지환급금이 지급되지 아니한 경우":"계속보험료 미납으로 계약이 해지되고 해지환급금도 나가지 않았을 때 부활을 청구할 수 있습니다.","제657조제1항의 통지를 받은 후 지체없이 지급할 보험금액을 정하고, 정하여진 날부터 10일 내에 피보험자 또는 보험수익자에게 지급한다":"약정이 없으면 통지를 받은 뒤 바로 지급액을 정하고 그날부터 10일 안에 지급해요.","제666조 기재사항 외에 건물이 목적이면 그 소재지, 구조와 용도를 기재한다":"화재보험증권에는 일반 기재사항에 더해 건물의 소재지, 구조, 용도를 적어야 해요.","중과실 불고지 시 체결일부터 5년 시점에는 해지 불가(3년 초과)":"중과실로 알리지 않았어도 체결 후 5년이면 계약일부터 3년이 지나 해지권이 없어집니다.","증권 교부는 성립요건이 아니다":"증권은 계약이 성립한 뒤에 교부하는 서류이므로 이것이 없다고 계약이 성립하지 않는 것은 아닙니다.","증권에 기명날인 또는 서명하는 자는 보험자이다":"증권에 서명이나 기명날인을 하는 사람은 계약자가 아니라 보험자입니다.","증권을 멸실 또는 현저하게 훼손한 때 보험계약자는 보험자에게 재교부를 청구할 수 있고, 증권 작성 비용은 보험계약자가 부담한다":"증권을 잃어버리거나 심하게 망가뜨린 계약자는 재교부를 청구하되 작성 비용은 직접 내야 해요.","지급하지 아니하는 경우 다른 약정이 없는 한 계약성립 후 2월이 경과하면 그 계약은 해제된 것으로 본다(별도 해제 의사표시 불요)":"첫 보험료를 안 내고 두 달이 지나면 해제 의사표시가 없어도 해제된 것으로 봅니다.","집합된 물건을 일괄하여 보험의 목적으로 한 때에는 피보험자의 가족과 사용인의 물건도 보험의 목적에 포함된 것으로 한다":"집합된 물건을 일괄해 보험에 들면 개별 물건 하나하나를 따지지 않고 전체를 목적으로 봅니다.","책임보험자는 피보험자가 보험기간 중의 사고로 제3자에게 배상할 책임을 진 경우 이를 보상할 책임이 있다":"책임보험은 피보험자가 제3자에게 배상할 책임을 졌을 때 그 부담을 보험자가 메워 주는 보험입니다.","청약·고지·통지·해지·취소 등 의사표시를 수령할 권한":"계속적 중개자는 계약자의 청약이나 해지 같은 의사표시를 수령할 권한이 없습니다.","청약과 승낙의 합의만으로 성립한다":"낙성계약은 청약과 승낙이 맞아떨어지면 곧바로 성립하고 다른 행위가 따로 필요하지 않은 계약이에요.","청약과 함께 보험료 상당액의 전부 또는 일부를 받음 → 다른 약정이 없으면 30일 내에 보험계약자에게 낙부의 통지를 발송 → 보험자의 책임 개시: 다른 약정이 없으면 최초 보험료의 지급을 받은 때":"청약과 함께 보험료를 받은 보험자는 정해진 기간 안에 승낙 여부를 알려야 하고 책임은 첫 보험료를 받은 때 시작해요.","청약은 보험계약자가 하고 보험자가 승낙한다":"청약을 하는 쪽은 보험계약자이고 보험자가 이를 받아들이는 승낙을 하는 순서입니다.","초과보험 계약이 보험계약자의 사기로 체결된 때에는 그 계약은 무효이다. 다만 보험자는 그 사실을 안 때까지의 보험료를 청구할 수 있다":"계약자의 사기로 맺은 초과보험은 무효이나 보험자는 안 때까지의 보험료를 받을 수 있습니다.","초과 여부를 가리는 가액은 계약당시의 가액에 의한다":"초과 여부는 계약 체결 당시의 가액을 기준으로 따집니다.","최고 없이 즉시 해지할 수 없고, 「해지된 것으로 본다」도 아님":"독촉 없이 곧바로 해지하는 것도, 해지된 것으로 간주하는 것도 허용되지 않아요.","최고 후 해지(제650조②)":"계속보험료를 내지 않으면 독촉을 거친 뒤에 해지하는 방식으로 처리됩니다.","취소권자는 보험계약자(피보험자·수익자 아님)":"약관 설명의무 위반으로 계약을 취소할 수 있는 사람은 계약자뿐이고 피보험자나 수익자는 아닙니다.","타인을 위한 손해보험의 타인(피보험자)도 고지의무를 부담":"타인을 위한 손해보험에서는 그 타인인 피보험자도 중요한 사항을 알릴 고지의무를 집니다.","타인을 위한 손해보험의 타인(피보험자)도 통지의무를 진다":"통지의무는 타인을 위한 손해보험의 타인, 곧 피보험자에게도 있어요.","타인의 동의를 얻지 아니하거나 보험증권을 소지하지 아니하면 해지하지 못한다":"타인을 위한 보험은 그 타인의 동의나 보험증권 소지가 없으면 계약자가 마음대로 해지하지 못하죠.","통지를 하지 아니한 경우 보험자의 해지권은 상법에 없다":"통지를 하지 않았다고 해서 보험자가 해지할 수 있다는 상법 규정은 없습니다.","통지를 해태한 때 보험자는 그 사실을 안 날부터 1월 내에 한하여 계약을 해지할 수 있다":"통지를 게을리하면 보험자는 그 사실을 안 날부터 한 달 안에 계약을 해지할 수 있습니다.","통지의무를 해태함으로 인하여 손해가 증가된 때 보험자는 그 증가된 손해를 보상할 책임이 없다. 해지권은 규정하지 않는다":"통지를 게을리해 늘어난 손해는 보험자가 책임지지 않으며 해지권은 따로 두지 않았어요.","통지의무자는 보험계약자, 피보험자, 보험수익자 모두이다. 통지 상대방은 보험자이다":"통지를 해야 하는 사람은 계약자, 피보험자, 수익자 모두이고 받는 상대는 보험자예요.","특별한 위험을 예기하여 보험료를 정한 경우 그 위험이 보험기간 중 소멸하면 보험계약자는 그 후의 보험료 감액을 청구할 수 있다":"특별한 위험을 감안해 올려 정한 보험료는 그 위험이 보험기간 중 없어지면 이후분의 감액을 청구할 수 있죠.","특정한 보험자를 위하여 계속적으로 보험계약의 체결을 중개하는 자는 제1항 제1호(보험자가 작성한 영수증을 보험계약자에게 교부하는 경우만 해당)와 제2호의 권한만 있다":"보험설계사 같은 계속적 중개자는 영수증을 교부하는 경우의 보험료 수령과 증권 교부 권한만 가집니다.","특정한 타인을 위한 보험에서 보험계약자가 지체한 때 보험자는 그 타인에게도 상당한 기간을 정하여 최고한 후가 아니면 계약을 해제 또는 해지하지 못한다":"계약자가 늦게 낼 때 특정 타인을 위한 보험이라면 그 타인에게도 독촉 기간을 준 뒤에야 해제나 해지가 가능합니다.","특정한 타인을 위한 보험에서 보험료 지급이 지체되면 보험자는 그 타인에게도 상당한 기간을 정해 최고한 후가 아니면 해제·해지하지 못한다":"특정 타인을 위한 보험에서 계약자가 보험료를 늦게 내면 보험자는 그 타인에게도 기간을 주고 독촉해야 해지할 수 있습니다.","피보험이익을 금전적으로 산정 또는 평가한 액수":"보험가액은 피보험이익을 돈으로 평가한 금액을 뜻해요.","피보험이익의 전부 또는 일부가 멸실되거나 감손된 것":"손해는 피보험이익의 전부나 일부가 사라지거나 가치가 줄어든 상태를 말해요.","피보험이익의 주체로서 보험사고가 발생한 때 보험금을 받을 자":"피보험자는 보험이익이 걸린 재산의 주체여서 사고가 나면 보험금을 받을 지위에 있는 사람이죠.","피보험자가 고의 또는 중과실로 손해방지의무를 위반":"의무를 어긴 정도가 고의나 중과실이라면 책임이 문제 되는 상황입니다.","피보험자가 담보 제공 또는 공탁으로 재판 집행을 면할 수 있는 경우, 보험금액의 한도 내에서 보험자에게 그 담보 제공 또는 공탁을 청구할 수 있다":"담보를 내거나 공탁하면 집행을 피할 수 있을 때, 보험금액 한도에서 보험자에게 그 담보나 공탁을 하도록 청구할 수 있죠.","피보험자가 보험의 목적을 양도한 때에는 양수인은 보험계약상의 권리와 의무를 승계한 것으로 추정한다. (간주가 아니다. 권리만 승계하는 것이 아니다)":"목적을 넘겨받은 양수인은 계약상 권리뿐 아니라 의무까지 이어받은 것으로 추정됩니다.","피보험자가 제3자의 청구를 방어하기 위하여 지출한 재판상 또는 재판외의 필요비용은 보험의 목적에 포함된 것으로 하고, 피보험자는 보험자에게 그 비용의 선급을 청구할 수 있다":"제3자의 청구에 맞서 쓴 재판상 또는 재판 밖의 필요비용도 보험 목적에 포함되고 미리 달라고 할 수 있어요.","피보험자나 보험수익자가 보험료를 지급하거나 보험계약에 관한 의사표시를 할 의무가 있는 경우에는 제1항부터 제3항까지를 그 피보험자나 보험수익자에게도 적용한다":"피보험자나 수익자가 보험료를 내거나 의사표시를 할 의무를 지는 경우에는 이들에게도 같은 규정이 적용됩니다.","피보험자는 보험금액 전부를 지급받은 후에는 잔존물을 임의로 처분할 수 없다":"보험금 전액을 받은 피보험자는 잔존물이 보험자 권리로 넘어갔으므로 마음대로 처분하지 못합니다.","피보험자는 보험사고 발생을 안 때 지체없이 보험자에게 통지를 발송하여야 한다":"피보험자가 사고를 알게 되면 바로 보험자에게 알리는 통지를 보내야 하는 의무가 있어요.","피보험자의 주소, 성명 또는 상호":"피보험자의 주소와 성명 또는 상호도 증권에 적는 법정 기재사항에 해당합니다.","필요·유익 비용과 보상액이 보험금액을 초과한 경우라도 보험자가 이를 부담한다(보험금액 한도 아님)":"방지 비용과 보상액을 더한 금액이 보험금액보다 커도 그 초과분까지 보험자가 부담하죠.","하나의 보험계약을 수인의 보험자와 체결하는 공동보험과 구별된다":"공동보험은 하나의 보험계약에 여러 보험자가 함께 참여하는 점에서 중복보험과 다릅니다.","해상보험 기타 이와 유사한 보험도 같다":"해상보험이나 이와 비슷한 보험도 재보험처럼 불리한 특약이 허용되는 예외입니다.","해지는 의사표시로 하는 것이지 당연히 해지된 것으로 보지 않는다":"보험자가 해지 의사를 표시해야 효력이 생기며, 위험이 늘었다고 계약이 저절로 끝나지 않아요.","해지 시 다른 약정이 없으면 미경과보험료 반환 청구 가능":"임의로 해지하면 다른 합의가 없는 한 남은 기간 몫의 보험료를 돌려 달라고 할 수 있습니다.","해지와 증액은 보험자가 선택한다(증액만 가능하다거나 해지만 가능하다는 말은 틀림)":"해지할지 보험료를 올릴지는 보험자가 고르는 것이라 한쪽만 가능하다고 한정하면 틀립니다.","해지하지 아니한 보험계약은 파산선고 후 3월을 경과한 때 그 효력을 잃는다":"해지하지 않고 두면 파산선고 후 석 달이 지나는 시점에 계약이 자동으로 효력을 잃습니다.","화재 건물의 철거비와 폐기물처리비는 화재와 상당인과관계가 있는 건물수리비에 포함된다":"철거비와 폐기물처리비도 화재와 상당인과관계가 있는 수리비 범위에 들어갑니다.","화재로 다른 곳에 옮겨놓은 물건의 도난으로 인한 손해는 보상 대상이 아니다":"화재로 옮겨 둔 물건을 도난당한 손해는 보상 대상에서 빠집니다.","화재보험계약의 보험자는 화재로 인하여 생길 손해를 보상할 책임이 있다":"화재보험자는 화재 때문에 생기는 손해를 보상하는 책임을 지는 계약 당사자예요.","화재보험의 보험자는 소방 또는 손해 감소에 필요한 조치로 인하여 생긴 손해를 보상할 책임이 있다":"화재보험자는 불을 끄거나 손해를 줄이려고 취한 조치에서 생긴 손해도 보상해야 합니다.","화재와 손해 사이에 상당인과관계가 필요하다":"보상 대상이 되려면 화재와 손해 사이에 상당인과관계가 있어야 합니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
